COMMENT ON FUNCTION auth_management.revoke_role_from_user(p_user_id uuid, p_role auth_management.gamilit_role, p_revoked_by uuid) IS 'Revoca un rol de un usuario (soft delete) con validaciones de seguridad y auditoría';


--
-- Name: update_user_preferences(uuid, character varying, character varying, boolean, boolean, boolean, boolean, jsonb); Type: FUNCTION; Schema: auth_management; Owner: postgres
--

CREATE FUNCTION auth_management.update_user_preferences(p_user_id uuid, p_theme character varying DEFAULT NULL::character varying, p_language character varying DEFAULT NULL::character varying, p_notifications_enabled boolean DEFAULT NULL::boolean, p_email_notifications boolean DEFAULT NULL::boolean, p_sound_enabled boolean DEFAULT NULL::boolean, p_tutorial_completed boolean DEFAULT NULL::boolean, p_preferences jsonb DEFAULT NULL::jsonb) RETURNS TABLE(user_id uuid, theme character varying, language character varying, notifications_enabled boolean, email_notifications boolean, sound_enabled boolean, tutorial_completed boolean, preferences jsonb, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Verify user exists
    IF NOT EXISTS (SELECT 1 FROM auth_management.profiles WHERE id = p_user_id) THEN
        RAISE EXCEPTION 'User with ID % does not exist', p_user_id;
    END IF;

    -- Update preferences, creating if not exists
    INSERT INTO auth_management.user_preferences (
        user_id, theme, language, notifications_enabled,
        email_notifications, sound_enabled, tutorial_completed, preferences
    ) VALUES (
        p_user_id,
        COALESCE(p_theme, 'light'),
        COALESCE(p_language, 'es'),
        COALESCE(p_notifications_enabled, true),
        COALESCE(p_email_notifications, true),
        COALESCE(p_sound_enabled, true),
        COALESCE(p_tutorial_completed, false),
        COALESCE(p_preferences, '{}')
    )
    ON CONFLICT (user_id) DO UPDATE SET
        theme = COALESCE(p_theme, user_preferences.theme),
        language = COALESCE(p_language, user_preferences.language),
        notifications_enabled = COALESCE(p_notifications_enabled, user_preferences.notifications_enabled),
        email_notifications = COALESCE(p_email_notifications, user_preferences.email_notifications),
        sound_enabled = COALESCE(p_sound_enabled, user_preferences.sound_enabled),
        tutorial_completed = COALESCE(p_tutorial_completed, user_preferences.tutorial_completed),
        preferences = CASE
            WHEN p_preferences IS NOT NULL THEN p_preferences
            ELSE user_preferences.preferences
        END,
        updated_at = NOW()
    RETURNING
        user_preferences.user_id,
        user_preferences.theme,
        user_preferences.language,
        user_preferences.notifications_enabled,
        user_preferences.email_notifications,
        user_preferences.sound_enabled,
        user_preferences.tutorial_completed,
        user_preferences.preferences,
        user_preferences.updated_at;
END;
$$;


