--
-- Name: get_unread_count(uuid, uuid); Type: FUNCTION; Schema: communication; Owner: postgres
--

CREATE FUNCTION communication.get_unread_count(p_user_id uuid, p_classroom_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*)
    INTO v_count
    FROM communication.messages
    WHERE recipient_id = p_user_id
      AND is_read = FALSE
      AND is_deleted = FALSE
      AND (p_classroom_id IS NULL OR classroom_id = p_classroom_id);

    RETURN v_count;
END;
$$;


