--

CREATE FUNCTION data_warehouse.validate_prediction(p_prediction_id uuid, p_actual_outcome jsonb, p_accurate boolean) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE data_warehouse.ml_prediction_logs
    SET
        actual_outcome_json = p_actual_outcome,
        prediction_accurate = p_accurate,
        validated_at = NOW()
    WHERE prediction_id = p_prediction_id
    AND validated_at IS NULL;

    RETURN FOUND;
END;
$$;


