--
-- Name: calculate_level_from_xp(integer); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.calculate_level_from_xp(p_xp integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN FLOOR(SQRT(p_xp::numeric / 100.0)) + 1;
END;
$$;


