--
-- Name: calculate_maya_rank_from_xp(integer); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.calculate_maya_rank_from_xp(xp integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- v2.1 thresholds (synced with 03-maya_ranks.sql seeds)
    IF xp < 500 THEN
        RETURN 'Ajaw';
    ELSIF xp < 1000 THEN
        RETURN 'Nacom';
    ELSIF xp < 1500 THEN
        RETURN 'Ah K''in';
    ELSIF xp < 1900 THEN
        RETURN 'Halach Uinic';
    ELSE
        RETURN 'K''uk''ulkan';
    END IF;
END;
$$;


ALTER FUNCTION gamification_system.calculate_maya_rank_from_xp(xp integer) OWNER TO postgres;

--
-- Name: FUNCTION calculate_maya_rank_from_xp(xp integer); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.calculate_maya_rank_from_xp(xp integer) IS 'Pure function: Calculates Maya rank from XP value without database queries.
     IMMUTABLE for query optimization. v2.1 Thresholds: Ajaw(0-499), Nacom(500-999),
     Ah K''in(1000-1499), Halach Uinic(1500-1899), K''uk''ulkan(1900+).';


--
-- Name: calculate_rank_progress_percentage(integer, text); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.calculate_rank_progress_percentage(xp integer, rank text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    xp_in_rank INTEGER;
    rank_size INTEGER;
BEGIN
    -- Calculate XP earned within the current rank (v2.1 thresholds)
    CASE rank
        WHEN 'Ajaw' THEN
            xp_in_rank := xp;           -- 0-499 XP
            rank_size := 500;
        WHEN 'Nacom' THEN
            xp_in_rank := xp - 500;     -- 500-999 XP
            rank_size := 500;
        WHEN 'Ah K''in' THEN
            xp_in_rank := xp - 1000;    -- 1000-1499 XP
            rank_size := 500;
        WHEN 'Halach Uinic' THEN
            xp_in_rank := xp - 1500;    -- 1500-1899 XP
            rank_size := 400;
        WHEN 'K''uk''ulkan' THEN
            -- Maximum rank always shows 100%
            RETURN 100.00;
        ELSE
            -- Unknown rank, return 0
            RETURN 0.00;
    END CASE;

    -- Calculate percentage (0-100)
    IF rank_size > 0 THEN
        RETURN LEAST(100.00, (xp_in_rank::NUMERIC / rank_size::NUMERIC) * 100);
    ELSE
        RETURN 0.00;
    END IF;
END;
$$;


ALTER FUNCTION gamification_system.calculate_rank_progress_percentage(xp integer, rank text) OWNER TO postgres;

--
-- Name: FUNCTION calculate_rank_progress_percentage(xp integer, rank text); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.calculate_rank_progress_percentage(xp integer, rank text) IS 'Pure function: Calculates percentage progress within a Maya rank.
     Returns 0-100 based on XP earned within the rank. Maximum rank returns 100%.
     v2.1 thresholds: Ajaw(500), Nacom(500), Ah K''in(500), Halach Uinic(400).
     IMMUTABLE for query optimization.';


--
-- Name: calculate_user_rank(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.calculate_user_rank(p_user_id uuid) RETURNS TABLE(user_id uuid, current_rank character varying, next_rank character varying, xp_to_next_rank bigint, modules_to_next_rank integer, rank_percentage numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_total_xp BIGINT;
    v_modules_completed INTEGER;  -- Renombrado: missions → modules
    v_current_rank VARCHAR;
    v_next_rank VARCHAR;
    v_next_rank_xp BIGINT;
    v_next_rank_modules INTEGER;  -- Renombrado: missions → modules
BEGIN
    -- Obtener estadísticas del usuario
    -- CORR-P0-001: Usar modules_completed en lugar de missions_completed (columna no existe)
    -- FIX: Usar alias 'us' para evitar ambigüedad con output column 'user_id'
    SELECT us.total_xp, us.modules_completed INTO v_total_xp, v_modules_completed
    FROM gamification_system.user_stats us
    WHERE us.user_id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Determinar rango actual basado en XP
    -- FIX: Usar alias 'ur' para evitar ambigüedad
    SELECT ur.current_rank INTO v_current_rank
    FROM gamification_system.user_ranks ur
    WHERE ur.user_id = p_user_id
    AND ur.is_current = true;

    -- Obtener siguiente rango desde maya_ranks
    -- NOTA: Columna correcta es rank_name (ENUM maya_rank), no name
    SELECT rank_name::VARCHAR, min_xp_required, COALESCE(modules_required, 0)
    INTO v_next_rank, v_next_rank_xp, v_next_rank_modules
    FROM gamification_system.maya_ranks
    WHERE rank_name::VARCHAR > COALESCE(v_current_rank, 'Ajaw')
    ORDER BY min_xp_required ASC
    LIMIT 1;

    IF v_next_rank IS NULL THEN
        -- Usuario está en rango máximo
        v_next_rank := v_current_rank;
        v_next_rank_xp := v_total_xp;
        v_next_rank_modules := v_modules_completed;
    END IF;

    RETURN QUERY SELECT
        p_user_id,
        COALESCE(v_current_rank, 'Ajaw'::VARCHAR),
        v_next_rank,
        GREATEST(0, v_next_rank_xp - v_total_xp),
        GREATEST(0, COALESCE(v_next_rank_modules, 0) - v_modules_completed),
        LEAST(100.0::NUMERIC, (v_total_xp::NUMERIC / NULLIF(v_next_rank_xp, 0)) * 100);
END;
$$;


ALTER FUNCTION gamification_system.calculate_user_rank(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION calculate_user_rank(p_user_id uuid); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.calculate_user_rank(p_user_id uuid) IS 'Calcula el rango actual del usuario basado en XP y módulos completados';


--
-- Name: check_and_grant_achievements(uuid, character varying, integer); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.check_and_grant_achievements(p_user_id uuid, p_event_type character varying, p_event_value integer DEFAULT 1) RETURNS TABLE(achievement_id uuid, achievement_name character varying, xp_granted integer, coins_granted integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_achievement RECORD;
    v_user_stats RECORD;
    v_condition_met BOOLEAN;
    -- CORR-DUP-002: Variables v_current_balance y v_new_balance removidas
    -- ya que las recompensas se otorgan en claim_achievement_reward, no aquí
    v_xp_reward INTEGER;
    v_condition_value INTEGER;
BEGIN
    -- Obtener estadisticas del usuario
    SELECT * INTO v_user_stats
    FROM gamification_system.user_stats
    WHERE user_id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Iterar sobre achievements activos no otorgados
    -- CORRECCION: Usar JSONB conditions->>'type' en lugar de columna condition_type
    -- CORRECCION: Extraer xp desde rewards JSONB
    FOR v_achievement IN
        SELECT
            a.id,
            a.name,
            a.conditions->>'type' as condition_type,
            COALESCE((a.conditions->'requirements'->>'target')::integer,
                     (a.conditions->'requirements'->>'exercises_completed')::integer,
                     (a.conditions->'requirements'->>'total_xp')::integer,
                     (a.conditions->'requirements'->>'streak_days')::integer,
                     10) as condition_value,
            COALESCE((a.rewards->>'xp')::integer, 0) as xp_reward,
            COALESCE(a.ml_coins_reward, (a.rewards->>'ml_coins')::integer, 0) as ml_coins_reward
        FROM gamification_system.achievements a
        WHERE a.is_active = true
          AND a.conditions->>'type' = p_event_type
          AND NOT EXISTS (
              SELECT 1 FROM gamification_system.user_achievements ua
              WHERE ua.user_id = p_user_id AND ua.achievement_id = a.id AND ua.is_completed = true
          )
    LOOP
        v_condition_met := false;
        v_condition_value := v_achievement.condition_value;
        v_xp_reward := v_achievement.xp_reward;

        -- Evaluar condicion segun tipo
        CASE v_achievement.condition_type
            WHEN 'MISSIONS_COMPLETED' THEN
                -- CORRECCION: Usar modules_completed como alternativa (missions_completed no existe)
                v_condition_met := COALESCE(v_user_stats.modules_completed, 0) >= v_condition_value;
            WHEN 'TOTAL_XP' THEN
                v_condition_met := COALESCE(v_user_stats.total_xp, 0) >= v_condition_value;
            WHEN 'STREAK_DAYS' THEN
                v_condition_met := COALESCE(v_user_stats.current_streak, 0) >= v_condition_value;
            WHEN 'ACHIEVEMENTS_EARNED' THEN
                v_condition_met := COALESCE(v_user_stats.achievements_earned, 0) >= v_condition_value;
            WHEN 'EXERCISES_COMPLETED' THEN
                v_condition_met := COALESCE(v_user_stats.exercises_completed, 0) >= v_condition_value;
            WHEN 'progress' THEN
                -- Tipo generico de progreso
                v_condition_met := COALESCE(v_user_stats.exercises_completed, 0) >= v_condition_value;
            ELSE
                v_condition_met := p_event_value >= v_condition_value;
        END CASE;

        -- Si la condicion se cumple, otorgar achievement
        IF v_condition_met THEN
            -- CORRECCION: Insertar con is_completed y completed_at en lugar de earned_at
            INSERT INTO gamification_system.user_achievements (
                user_id, achievement_id, is_completed, completed_at, progress, max_progress
            ) VALUES (
                p_user_id, v_achievement.id, true, NOW(), 100, 100
            )
            ON CONFLICT (user_id, achievement_id) DO UPDATE
            SET is_completed = true, completed_at = NOW(), progress = 100;

            -- ========== MODELO CLAIM-TO-EARN (CORR-DUP-002) ==========
            -- NOTA: XP y ML Coins NO se otorgan aquí.
            -- Se otorgan ÚNICAMENTE al reclamar via claim_achievement_reward()
            -- Esto evita la doble/triple distribución de rewards detectada en
            -- ANALISIS-DUPLICADOS-ACHIEVEMENTS-2026-01-10.md
            --
            -- El trigger fn_on_achievement_unlocked creará una notificación
            -- indicando al usuario que debe reclamar sus recompensas.

            -- Solo incrementar contador de achievements earned
            UPDATE gamification_system.user_stats
            SET
                achievements_earned = COALESCE(achievements_earned, 0) + 1,
                updated_at = NOW()
            WHERE user_id = p_user_id;

            -- NO registrar transaccion de coins aquí - se hace en claim_achievement_reward

            -- Retornar el achievement desbloqueado (rewards pendientes de claim)
            RETURN QUERY SELECT
                v_achievement.id,
                v_achievement.name::VARCHAR(100),
                v_xp_reward,  -- Estos son los rewards PENDIENTES, no otorgados
                COALESCE(v_achievement.ml_coins_reward, 0)::INTEGER;
        END IF;
    END LOOP;
END;
$$;


