--
-- Name: update_leaderboard_streaks(uuid); Type: FUNCTION; Schema: gamification_system; Owner: postgres
--

CREATE FUNCTION gamification_system.update_leaderboard_streaks(p_user_id uuid) RETURNS TABLE(current_streak integer, longest_streak integer, streak_maintained boolean, bonus_xp integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_last_activity DATE;
    v_current_streak INTEGER;
    v_longest_streak INTEGER;
    v_streak_maintained BOOLEAN := false;
    v_bonus_xp INTEGER := 0;
BEGIN
    -- Obtener información de racha actual
    -- NOTA: last_activity_at es TIMESTAMP WITH TIME ZONE, se castea a DATE
    SELECT
        COALESCE(us.last_activity_at::DATE, CURRENT_DATE),
        COALESCE(us.current_streak, 0),
        COALESCE(us.max_streak, 0)
    INTO v_last_activity, v_current_streak, v_longest_streak
    FROM gamification_system.user_stats us
    WHERE us.user_id = p_user_id;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    -- Verificar racha
    IF v_last_activity = CURRENT_DATE THEN
        -- Ya registró actividad hoy
        v_streak_maintained := true;
    ELSIF v_last_activity = CURRENT_DATE - INTERVAL '1 day' THEN
        -- Mantiene racha
        v_current_streak := v_current_streak + 1;
        v_streak_maintained := true;

        -- Bonus XP por racha (10 XP por cada día de racha)
        v_bonus_xp := v_current_streak * 10;

        -- Actualizar racha y otorgar bonus
        UPDATE gamification_system.user_stats
        SET
            current_streak = v_current_streak,
            max_streak = GREATEST(max_streak, v_current_streak),
            last_activity_at = NOW(),
            total_xp = total_xp + v_bonus_xp,
            updated_at = NOW()
        WHERE user_id = p_user_id;

        v_longest_streak := GREATEST(v_longest_streak, v_current_streak);
    ELSE
        -- Racha rota
        v_current_streak := 1;
        v_streak_maintained := false;

        UPDATE gamification_system.user_stats
        SET
            current_streak = 1,
            last_activity_at = NOW(),
            updated_at = NOW()
        WHERE user_id = p_user_id;
    END IF;

    RETURN QUERY SELECT
        v_current_streak,
        v_longest_streak,
        v_streak_maintained,
        v_bonus_xp;
END;
$$;


