-- Name: FUNCTION update_user_rank(p_user_id uuid); Type: COMMENT; Schema: gamification_system; Owner: postgres
--

COMMENT ON FUNCTION gamification_system.update_user_rank(p_user_id uuid) IS 'Actualiza el rango del usuario basado en XP total y otorga recompensas. Lee configuración dinámica desde maya_ranks table.';


--
-- Name: assign_default_classroom(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.assign_default_classroom() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_default_classroom_id UUID;
    v_error_message TEXT;
    v_error_detail TEXT;
    v_error_code TEXT;
BEGIN
    -- Solo procesar estudiantes
    IF NEW.role != 'student' THEN
        RETURN NEW;
    END IF;

    -- Buscar el classroom default
    SELECT id INTO v_default_classroom_id
    FROM social_features.classrooms
    WHERE metadata->>'is_default' = 'true'
      AND is_active = true
    LIMIT 1;

    -- Si no existe classroom default, buscar por código
    IF v_default_classroom_id IS NULL THEN
        SELECT id INTO v_default_classroom_id
        FROM social_features.classrooms
        WHERE code = 'DEFAULT'
          AND is_active = true
        LIMIT 1;
    END IF;

    -- Si no hay classroom default, no hacer nada (warning silencioso)
    IF v_default_classroom_id IS NULL THEN
        RAISE WARNING 'No se encontró classroom default. Estudiante % no asignado automáticamente.', NEW.id;
        RETURN NEW;
    END IF;

    -- Crear membership en classroom default
    -- Nota: enrollment_method usa 'admin_add' porque es asignación automática del sistema
    INSERT INTO social_features.classroom_members (
        id,
        classroom_id,
        student_id,
        enrollment_date,
        enrollment_method,
        status,
        metadata,
        created_at,
        updated_at
    ) VALUES (
        gen_random_uuid(),
        v_default_classroom_id,
        NEW.id,  -- profiles.id
        NOW(),
        'admin_add',  -- Válido según CHECK constraint
        'active',
        jsonb_build_object(
            'auto_assigned', true,
            'assigned_at', NOW()::text,
            'reason', 'Asignación automática a classroom default en registro'
        ),
        NOW(),
        NOW()
    )
    ON CONFLICT (classroom_id, student_id) DO NOTHING;  -- Evitar duplicados

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- P1-001: Capturar error sin bloquear creación de perfil
        GET STACKED DIAGNOSTICS
            v_error_message = MESSAGE_TEXT,
            v_error_detail = PG_EXCEPTION_DETAIL,
            v_error_code = RETURNED_SQLSTATE;

        RAISE WARNING '[P1-001] Error asignando classroom default para usuario %: % (SQLSTATE: %)',
            NEW.id, v_error_message, v_error_code;

        -- Registrar en pending_user_initialization para retry posterior
        BEGIN
            INSERT INTO audit_logging.pending_user_initialization (
                user_id,
                profile_id,
                tenant_id,
                error_message,
                error_code,
                error_detail,
                trigger_name,
                function_name,
                status,
                next_retry_at
            ) VALUES (
                NEW.user_id,
                NEW.id,
                NEW.tenant_id,
                v_error_message,
                v_error_code,
                v_error_detail,
                TG_NAME,
                'gamilit.assign_default_classroom',
                'pending',
                gamilit.now_mexico() + INTERVAL '5 minutes'
            );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING '[P1-001] No se pudo registrar error de classroom: %', SQLERRM;
        END;

        RETURN NEW;  -- Permite creación de perfil aunque falle asignación
END;
$$;


ALTER FUNCTION gamilit.assign_default_classroom() OWNER TO postgres;

--
-- Name: FUNCTION assign_default_classroom(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.assign_default_classroom() IS 'Asigna automáticamente estudiantes nuevos al classroom default (Sin Asignar)';


--
-- Name: assign_default_classroom_for_user(uuid); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.assign_default_classroom_for_user(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'gamilit', 'auth_management', 'social_features'
    AS $$
DECLARE
    v_profile RECORD;
    v_default_classroom_id UUID;
BEGIN
    -- Obtener perfil del usuario
    SELECT id, user_id, tenant_id, role
    INTO v_profile
    FROM auth_management.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RAISE WARNING 'Profile not found for user_id: %', p_user_id;
        RETURN FALSE;
    END IF;

    -- Solo procesar estudiantes
    IF v_profile.role != 'student' THEN
        RETURN TRUE;  -- OK, no requiere asignacion
    END IF;

    -- Verificar si ya tiene classroom activo
    IF EXISTS (
        SELECT 1 FROM social_features.classroom_members
        WHERE student_id = v_profile.id AND is_active = TRUE
    ) THEN
        RETURN TRUE;  -- Ya tiene classroom
    END IF;

    -- Buscar classroom default por metadata
    SELECT id INTO v_default_classroom_id
    FROM social_features.classrooms
    WHERE metadata->>'is_default' = 'true'
      AND is_active = true
    LIMIT 1;

    -- Fallback: buscar por codigo DEFAULT
    IF v_default_classroom_id IS NULL THEN
        SELECT id INTO v_default_classroom_id
        FROM social_features.classrooms
        WHERE code = 'DEFAULT'
          AND is_active = true
        LIMIT 1;
    END IF;

    IF v_default_classroom_id IS NULL THEN
        RAISE WARNING 'No default classroom found for user: %', p_user_id;
        RETURN FALSE;
    END IF;

    -- Asignar al classroom default
    INSERT INTO social_features.classroom_members (
        id,
        classroom_id,
        student_id,
        enrollment_date,
        enrollment_method,
        status,
        metadata,
        created_at,
        updated_at
    ) VALUES (
        gen_random_uuid(),
        v_default_classroom_id,
        v_profile.id,
        NOW(),
        'admin_add',
        'active',
        jsonb_build_object(
            'auto_assigned', true,
            'assigned_at', NOW()::text,
            'reason', 'Reasignacion via retry_pending_initializations'
        ),
        NOW(),
        NOW()
    )
    ON CONFLICT (classroom_id, student_id) DO NOTHING;

    RETURN TRUE;

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error in assign_default_classroom_for_user(%): %', p_user_id, SQLERRM;
    RETURN FALSE;
END;
$$;


ALTER FUNCTION gamilit.assign_default_classroom_for_user(p_user_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION assign_default_classroom_for_user(p_user_id uuid); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.assign_default_classroom_for_user(p_user_id uuid) IS 'Wrapper callable para reintentar asignacion de classroom default.
Usado por audit_logging.retry_pending_initializations() para usuarios que fallaron durante trigger.
A diferencia de assign_default_classroom() (trigger), esta funcion recibe user_id directamente.';


--
-- Name: audit_profile_changes(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.audit_profile_changes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_error_message TEXT;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- Log role changes
        IF OLD.role != NEW.role THEN
            INSERT INTO audit_logging.audit_logs (
                event_type,
                action,
                resource_type,
                resource_id,
                actor_id,
                old_values,
                new_values,
                description
            ) VALUES (
                'role_changed',
                'UPDATE',
                'profile',
                NEW.id,
                NEW.id,
                jsonb_build_object('role', OLD.role),
                jsonb_build_object('role', NEW.role),
                format('User role changed from %s to %s', OLD.role, NEW.role)
            );
        END IF;

        -- Log status changes
        IF OLD.status != NEW.status THEN
            INSERT INTO audit_logging.audit_logs (
                event_type,
                action,
                resource_type,
                resource_id,
                actor_id,
                old_values,
                new_values,
                description
            ) VALUES (
                'status_changed',
                'UPDATE',
                'profile',
                NEW.id,
                NEW.id,
                jsonb_build_object('status', OLD.status),
                jsonb_build_object('status', NEW.status),
                format('User status changed from %s to %s', OLD.status, NEW.status)
            );
        END IF;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        -- P1-001: Capturar error de auditoría sin bloquear operación
        v_error_message := SQLERRM;
        RAISE WARNING '[P1-001] Error en auditoría de cambio de perfil %: %', NEW.id, v_error_message;
        -- Auditoría no es crítica, no bloquear la operación original
        RETURN NEW;
END;
$$;


