-- Name: set_profile_defaults(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.set_profile_defaults() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Set default authentication values if not provided
    IF NEW.is_active IS NULL THEN
        NEW.is_active := true;
    END IF;

    IF NEW.email_verified IS NULL THEN
        NEW.email_verified := true;
    END IF;

    RETURN NEW;
END;
$$;


