--
-- Name: update_user_stats_on_exercise_complete(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.update_user_stats_on_exercise_complete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_is_correct BOOLEAN;
    v_xp_earned INTEGER;
    v_coins_earned INTEGER;
BEGIN
    -- Determinar si el ejercicio fue completado correctamente
    v_is_correct := (NEW.is_correct = true OR NEW.score >= 60);

    -- Calcular XP y monedas ganadas
    IF v_is_correct THEN
        v_xp_earned := COALESCE(NEW.xp_earned, 10); -- Default 10 XP
        v_coins_earned := COALESCE(NEW.ml_coins_earned, 5); -- FIX: ml_coins_earned, no coins_earned
    ELSE
        v_xp_earned := 0;
        v_coins_earned := 0;
    END IF;

    -- Actualizar estadísticas del usuario
    UPDATE gamification_system.user_stats
    SET
        exercises_completed = CASE WHEN v_is_correct THEN exercises_completed + 1 ELSE exercises_completed END,
        perfect_scores = CASE WHEN v_is_correct AND NEW.score = 100 THEN perfect_scores + 1 ELSE perfect_scores END,
        total_xp = total_xp + v_xp_earned,
        ml_coins = ml_coins + v_coins_earned,                          -- FIX: ml_coins, no ml_coins_balance
        ml_coins_earned_total = ml_coins_earned_total + v_coins_earned, -- FIX: tracking total earned
        average_score = CASE WHEN v_is_correct THEN
            COALESCE((
                SELECT AVG(score)::numeric(5,2)
                FROM progress_tracking.exercise_attempts
                WHERE user_id = NEW.user_id AND is_correct = true
            ), 0)
        ELSE average_score END,
        last_activity_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico()
    WHERE user_id = NEW.user_id;

    -- Si no existe el registro de estadísticas, crearlo (UPSERT pattern)
    IF NOT FOUND THEN
        INSERT INTO gamification_system.user_stats (
            user_id,
            tenant_id,
            exercises_completed,
            perfect_scores,
            total_xp,
            ml_coins,                                                   -- FIX: ml_coins, no ml_coins_balance
            ml_coins_earned_total,
            average_score,
            last_activity_at
        ) VALUES (
            NEW.user_id,
            '00000000-0000-0000-0000-000000000000'::UUID,
            CASE WHEN v_is_correct THEN 1 ELSE 0 END,
            CASE WHEN v_is_correct AND NEW.score = 100 THEN 1 ELSE 0 END,
            v_xp_earned,
            100 + v_coins_earned, -- Balance inicial de 100
            v_coins_earned,
            CASE WHEN v_is_correct THEN NEW.score ELSE 0 END,
            gamilit.now_mexico()
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el insert del attempt
        RAISE WARNING 'Error al actualizar estadísticas de usuario %: %', NEW.user_id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.update_user_stats_on_exercise_complete() OWNER TO postgres;

--
-- Name: FUNCTION update_user_stats_on_exercise_complete(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.update_user_stats_on_exercise_complete() IS 'Trigger function que actualiza las estadísticas del usuario al completar un ejercicio. Incrementa contadores de ejercicios, XP, monedas ML y mantiene last_activity_at actualizado. Usa patrón UPSERT para crear registro de stats si no existe.';


--
-- Name: update_user_stats_on_submission_graded(); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.update_user_stats_on_submission_graded() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Validar que solo procesemos calificaciones nuevas
    -- Solo procesar si:
    -- 1. El status cambió a 'graded' o 'reviewed'
    -- 2. La respuesta es correcta
    -- 3. Hay XP a otorgar
    -- 4. El estado cambió (evitar re-disparos)
    IF NEW.status NOT IN ('graded', 'reviewed') THEN
        RETURN NEW;
    END IF;

    IF NEW.is_correct IS NOT TRUE THEN
        RETURN NEW;
    END IF;

    -- Evitar re-disparos cuando el status o is_correct no cambiaron
    IF OLD.status IS NOT DISTINCT FROM NEW.status
       AND OLD.is_correct IS NOT DISTINCT FROM NEW.is_correct THEN
        RETURN NEW;
    END IF;

    -- Actualizar estadísticas del usuario (patrón UPSERT)
    UPDATE gamification_system.user_stats
    SET
        exercises_completed = exercises_completed + 1,
        perfect_scores = CASE WHEN NEW.score = 100 THEN perfect_scores + 1 ELSE perfect_scores END,
        total_xp = total_xp + COALESCE(NEW.xp_earned, 0),
        ml_coins = ml_coins + COALESCE(NEW.ml_coins_earned, 0),
        ml_coins_earned_total = ml_coins_earned_total + COALESCE(NEW.ml_coins_earned, 0),
        average_score = COALESCE((
            SELECT AVG(score)::numeric(5,2)
            FROM progress_tracking.exercise_submissions
            WHERE user_id = NEW.user_id AND is_correct = true AND status IN ('graded', 'reviewed')
        ), 0),
        last_activity_at = gamilit.now_mexico(),
        updated_at = gamilit.now_mexico()
    WHERE user_id = NEW.user_id;

    -- Si no existe el registro de estadísticas, crearlo (UPSERT pattern)
    IF NOT FOUND THEN
        INSERT INTO gamification_system.user_stats (
            user_id,
            tenant_id,
            exercises_completed,
            perfect_scores,
            total_xp,
            ml_coins,
            ml_coins_earned_total,
            average_score,
            last_activity_at
        ) VALUES (
            NEW.user_id,
            '00000000-0000-0000-0000-000000000000'::UUID,
            1,
            CASE WHEN NEW.score = 100 THEN 1 ELSE 0 END,
            COALESCE(NEW.xp_earned, 0),
            100 + COALESCE(NEW.ml_coins_earned, 0), -- Balance inicial de 100
            COALESCE(NEW.ml_coins_earned, 0),
            NEW.score,
            gamilit.now_mexico()
        );
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error pero no bloquear el update de la submission
        RAISE WARNING 'Error al actualizar estadísticas de usuario % desde submission %: %',
            NEW.user_id, NEW.id, SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION gamilit.update_user_stats_on_submission_graded() OWNER TO postgres;

--
-- Name: FUNCTION update_user_stats_on_submission_graded(); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.update_user_stats_on_submission_graded() IS 'Trigger function que actualiza las estadísticas del usuario al calificarse una submission. Incrementa contadores de ejercicios, XP, monedas ML y mantiene last_activity_at actualizado. Usa patrón UPSERT para crear registro de stats si no existe. Complementa a update_user_stats_on_exercise_complete() para el flujo de submissions.';


--
-- Name: validate_date_range(timestamp without time zone, timestamp without time zone, integer); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.validate_date_range(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_max_range_days integer DEFAULT 365) RETURNS TABLE(is_valid boolean, validation_message text, days_in_range integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_days_difference INTEGER;
    v_message TEXT;
    v_is_valid BOOLEAN := TRUE;
BEGIN
    -- Check if start date is NULL or end date is NULL
    IF p_start_date IS NULL THEN
        v_is_valid := FALSE;
        v_message := 'Start date cannot be null';
    ELSIF p_end_date IS NULL THEN
        v_is_valid := FALSE;
        v_message := 'End date cannot be null';
    -- Check if start date is after end date
    ELSIF p_start_date > p_end_date THEN
        v_is_valid := FALSE;
        v_message := FORMAT('Start date (%s) cannot be after end date (%s)', p_start_date, p_end_date);
    -- Check if range exceeds maximum allowed days
    ELSIF (p_end_date - p_start_date) > (p_max_range_days || ' days')::INTERVAL THEN
        v_is_valid := FALSE;
        v_message := FORMAT('Date range exceeds maximum allowed duration of %L days', p_max_range_days);
    -- Check if dates are in the future (warning scenario)
    ELSIF p_start_date > NOW() AND p_end_date > NOW() THEN
        v_is_valid := TRUE;
        v_message := 'Date range is in the future (valid for scheduling)';
    ELSE
        v_is_valid := TRUE;
        v_message := 'Date range is valid';
    END IF;

    -- Calculate days in range
    v_days_difference := EXTRACT(DAY FROM (p_end_date - p_start_date))::INTEGER;

    RETURN QUERY SELECT
        v_is_valid,
        v_message,
        v_days_difference;

EXCEPTION WHEN OTHERS THEN
    RETURN QUERY SELECT
        FALSE,
        FORMAT('Error during date validation: %s', SQLERRM),
        0;
END;
$$;


ALTER FUNCTION gamilit.validate_date_range(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_max_range_days integer) OWNER TO postgres;

--
-- Name: FUNCTION validate_date_range(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_max_range_days integer); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.validate_date_range(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_max_range_days integer) IS 'Validates date ranges for logical correctness and ensures they don''t exceed maximum duration limits.
Parameters:
  - p_start_date: Start date/timestamp of the range
  - p_end_date: End date/timestamp of the range
  - p_max_range_days: Maximum allowed days in range (default: 365)
Returns:
  - is_valid: TRUE if date range is valid, FALSE otherwise
  - validation_message: Description of validation result
  - days_in_range: Number of days between start and end date
Validation Rules:
  1. Neither date can be NULL
  2. Start date must be <= end date
  3. Date range cannot exceed p_max_range_days
  4. Range can be in the future (for scheduling)
Example:
  SELECT validate_date_range(
    ''2025-01-01 00:00:00''::TIMESTAMP,
    ''2025-12-31 23:59:59''::TIMESTAMP,
    365
  );

  SELECT validate_date_range(
    NOW(),
    NOW() + INTERVAL ''30 days'',
    30
  );';


--
-- Name: validate_email_format(character varying); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.validate_email_format(p_email character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    -- Validate email format using regex pattern
    -- Basic pattern: local-part@domain.extension
    RETURN p_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$';
END;
$_$;


ALTER FUNCTION gamilit.validate_email_format(p_email character varying) OWNER TO postgres;

--
-- Name: FUNCTION validate_email_format(p_email character varying); Type: COMMENT; Schema: gamilit; Owner: postgres
--

COMMENT ON FUNCTION gamilit.validate_email_format(p_email character varying) IS 'Valida que el formato del email sea correcto usando patrón regex';


--
-- Name: validate_username(character varying); Type: FUNCTION; Schema: gamilit; Owner: postgres
--

CREATE FUNCTION gamilit.validate_username(p_username character varying) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    -- Validate username format:
    -- - Length between 3 and 30 characters
    -- - Only alphanumeric characters, hyphens, and underscores
    -- - Must start with alphanumeric
    -- - Must end with alphanumeric
    RETURN p_username ~ '^[A-Za-z0-9][A-Za-z0-9_-]{1,28}[A-Za-z0-9]$'
        OR p_username ~ '^[A-Za-z0-9]$';
END;
$_$;


