--
-- Name: queue_batch_notifications(uuid[], character varying, character varying, text, jsonb, character varying); Type: FUNCTION; Schema: notifications; Owner: postgres
--

CREATE FUNCTION notifications.queue_batch_notifications(p_user_ids uuid[], p_type character varying, p_title character varying, p_message text, p_data jsonb DEFAULT '{}'::jsonb, p_priority character varying DEFAULT 'normal'::character varying) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID;
    v_count INTEGER := 0;
    v_notification_id UUID;
BEGIN
    -- Validar que hay usuarios
    IF array_length(p_user_ids, 1) IS NULL OR array_length(p_user_ids, 1) = 0 THEN
        RAISE EXCEPTION 'No users provided for batch notification';
    END IF;

    -- Iterar sobre cada usuario y crear notificación
    FOREACH v_user_id IN ARRAY p_user_ids
    LOOP
        -- Usar la función send_notification para crear y encolar
        BEGIN
            v_notification_id := notifications.send_notification(
                v_user_id,
                p_type,
                p_title,
                p_message,
                p_data,
                p_priority
            );

            IF v_notification_id IS NOT NULL THEN
                v_count := v_count + 1;
            END IF;

        EXCEPTION
            WHEN OTHERS THEN
                -- Log del error pero continuar con los demás usuarios
                RAISE WARNING 'Error creating notification for user %: %', v_user_id, SQLERRM;
        END;
    END LOOP;

    RETURN v_count;
END;
$$;


ALTER FUNCTION notifications.queue_batch_notifications(p_user_ids uuid[], p_type character varying, p_title character varying, p_message text, p_data jsonb, p_priority character varying) OWNER TO postgres;

--
-- Name: FUNCTION queue_batch_notifications(p_user_ids uuid[], p_type character varying, p_title character varying, p_message text, p_data jsonb, p_priority character varying); Type: COMMENT; Schema: notifications; Owner: postgres
--

COMMENT ON FUNCTION notifications.queue_batch_notifications(p_user_ids uuid[], p_type character varying, p_title character varying, p_message text, p_data jsonb, p_priority character varying) IS 'Encola notificaciones masivas a múltiples usuarios de forma eficiente';


--
-- Name: send_notification(uuid, character varying, character varying, text, jsonb, character varying); Type: FUNCTION; Schema: notifications; Owner: postgres
--

CREATE FUNCTION notifications.send_notification(p_user_id uuid, p_type character varying, p_title character varying, p_message text, p_data jsonb DEFAULT '{}'::jsonb, p_priority character varying DEFAULT 'normal'::character varying) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_notification_id UUID;
    v_channels VARCHAR(50)[];
    v_prefs RECORD;
BEGIN
    -- Obtener preferencias del usuario para este tipo de notificación
    SELECT
        COALESCE(np.in_app_enabled, true) as in_app_enabled,
        COALESCE(np.email_enabled, true) as email_enabled,
        COALESCE(np.push_enabled, true) as push_enabled
    INTO v_prefs
    FROM notifications.notification_preferences np
    WHERE np.user_id = p_user_id
      AND np.notification_type = p_type
    LIMIT 1;

    -- Si no hay preferencias, usar valores por defecto (todos habilitados)
    IF v_prefs IS NULL THEN
        v_prefs := ROW(true, true, true);
    END IF;

    -- Construir array de canales habilitados
    v_channels := ARRAY[]::VARCHAR(50)[];

    IF v_prefs.in_app_enabled THEN
        v_channels := v_channels || 'in_app';
    END IF;

    IF v_prefs.email_enabled THEN
        v_channels := v_channels || 'email';
    END IF;

    IF v_prefs.push_enabled THEN
        v_channels := v_channels || 'push';
    END IF;

    -- Si no hay canales habilitados, usar solo in_app por defecto
    IF array_length(v_channels, 1) IS NULL OR array_length(v_channels, 1) = 0 THEN
        v_channels := ARRAY['in_app'];
    END IF;

    -- Crear notificación
    INSERT INTO notifications.notifications (
        user_id,
        type,
        title,
        message,
        data,
        priority,
        channels,
        status
    ) VALUES (
        p_user_id,
        p_type,
        p_title,
        p_message,
        p_data,
        p_priority,
        v_channels,
        'pending'
    ) RETURNING id INTO v_notification_id;

    -- Encolar para envío en cada canal habilitado
    INSERT INTO notifications.notification_queue (
        notification_id,
        channel,
        scheduled_for,
        priority,
        status
    )
    SELECT
        v_notification_id,
        unnest(v_channels),
        gamilit.now_mexico(),
        CASE p_priority
            WHEN 'urgent' THEN 10
            WHEN 'high' THEN 5
            WHEN 'normal' THEN 0
            ELSE -5
        END,
        'queued';

    RETURN v_notification_id;
END;
$$;


