--
-- Name: are_friends(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.are_friends(user1_id uuid, user2_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM social_features.friendships
        WHERE (user_id = user1_id AND friend_id = user2_id)
           OR (user_id = user2_id AND friend_id = user1_id)
    );
END;
$$;


ALTER FUNCTION social_features.are_friends(user1_id uuid, user2_id uuid) OWNER TO postgres;

