--
-- Name: block_user(uuid, uuid, character varying, text); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.block_user(p_blocker_id uuid, p_blocked_id uuid, p_reason character varying DEFAULT NULL::character varying, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar que no se bloquee a si mismo
    IF p_blocker_id = p_blocked_id THEN
        RETURN FALSE;
    END IF;

    -- Insertar bloqueo
    INSERT INTO social_features.user_blocks (blocker_id, blocked_id, reason, notes)
    VALUES (p_blocker_id, p_blocked_id, p_reason, p_notes)
    ON CONFLICT (blocker_id, blocked_id) DO UPDATE
    SET reason = EXCLUDED.reason,
        notes = EXCLUDED.notes;

    -- Eliminar amistad existente si hay (en cualquier direccion)
    DELETE FROM social_features.friendships
    WHERE (user_id = p_blocker_id AND friend_id = p_blocked_id)
       OR (user_id = p_blocked_id AND friend_id = p_blocker_id);

    -- Cancelar solicitudes de amistad pendientes (en cualquier direccion)
    DELETE FROM social_features.friend_requests
    WHERE status = 'pending'
      AND (
          (requester_id = p_blocker_id AND recipient_id = p_blocked_id)
          OR (requester_id = p_blocked_id AND recipient_id = p_blocker_id)
      );

    RETURN TRUE;
END;
$$;


ALTER FUNCTION social_features.block_user(p_blocker_id uuid, p_blocked_id uuid, p_reason character varying, p_notes text) OWNER TO postgres;

--
-- Name: FUNCTION block_user(p_blocker_id uuid, p_blocked_id uuid, p_reason character varying, p_notes text); Type: COMMENT; Schema: social_features; Owner: postgres
--

COMMENT ON FUNCTION social_features.block_user(p_blocker_id uuid, p_blocked_id uuid, p_reason character varying, p_notes text) IS 'Bloquea a un usuario. Tambien elimina amistad existente y cancela solicitudes pendientes.';


--
-- Name: can_interact(uuid, uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.can_interact(user1_id uuid, user2_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
BEGIN
    -- Pueden interactuar si NO hay bloqueo en ninguna direccion
    RETURN NOT social_features.is_blocked(user1_id, user2_id);
END;
$$;


