-- Name: FUNCTION cleanup_old_notifications(p_days_to_keep integer); Type: COMMENT; Schema: social_features; Owner: postgres
--

COMMENT ON FUNCTION social_features.cleanup_old_notifications(p_days_to_keep integer) IS 'Limpia notificaciones leídas más antiguas que el período especificado';


--
-- Name: count_blocked_users(uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.count_blocked_users(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    block_count INTEGER;
BEGIN
    SELECT COUNT(*)::INTEGER INTO block_count
    FROM social_features.user_blocks
    WHERE blocker_id = p_user_id;

    RETURN COALESCE(block_count, 0);
END;
$$;


