--
-- Name: count_friends(uuid); Type: FUNCTION; Schema: social_features; Owner: postgres
--

CREATE FUNCTION social_features.count_friends(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    friend_count INTEGER;
BEGIN
    SELECT COUNT(*)::INTEGER INTO friend_count
    FROM social_features.friendships
    WHERE user_id = p_user_id OR friend_id = p_user_id;

    RETURN COALESCE(friend_count, 0);
END;
$$;


