--

CREATE FUNCTION social_features.get_blocked_users(p_user_id uuid) RETURNS TABLE(blocked_id uuid, reason character varying, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        b.blocked_id,
        b.reason,
        b.created_at
    FROM social_features.user_blocks b
    WHERE b.blocker_id = p_user_id
    ORDER BY b.created_at DESC;
END;
$$;


