--
-- Name: recent_admin_actions; Type: VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE VIEW admin_dashboard.recent_admin_actions AS
 SELECT al.id,
    al.action,
    al.resource_type,
    al.resource_id,
    al.description,
    al.status,
    al.created_at,
    u.email AS admin_email,
    p.full_name AS admin_name
   FROM ((audit_logging.audit_logs al
     LEFT JOIN auth.users u ON ((al.actor_id = u.id)))
     LEFT JOIN auth_management.profiles p ON ((al.actor_id = p.id)))
  WHERE (al.event_type = 'admin_action'::text)
  ORDER BY al.created_at DESC
 LIMIT 100;


