--
-- Name: system_overview_mv; Type: MATERIALIZED VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE MATERIALIZED VIEW admin_dashboard.system_overview_mv AS
 SELECT now() AS snapshot_timestamp,
    ( SELECT count(*) AS count
           FROM auth_management.profiles
          WHERE (profiles.status = 'active'::auth_management.user_status)) AS total_active_users,
    ( SELECT count(*) AS count
           FROM auth_management.user_roles
          WHERE ((user_roles.role = 'student'::auth_management.gamilit_role) AND (user_roles.is_active = true))) AS total_students,
    ( SELECT count(*) AS count
           FROM auth_management.user_roles
          WHERE ((user_roles.role = 'admin_teacher'::auth_management.gamilit_role) AND (user_roles.is_active = true))) AS total_teachers,
    ( SELECT count(*) AS count
           FROM auth_management.profiles
          WHERE (profiles.created_at >= (CURRENT_DATE - '7 days'::interval))) AS new_users_week,
    ( SELECT count(*) AS count
           FROM auth_management.profiles
          WHERE (profiles.created_at >= (CURRENT_DATE - '30 days'::interval))) AS new_users_month,
    ( SELECT count(*) AS count
           FROM social_features.classrooms
          WHERE (classrooms.is_active = true)) AS total_classrooms,
    ( SELECT count(*) AS count
           FROM social_features.classroom_members
          WHERE (classroom_members.is_active = true)) AS total_enrollments,
    ( SELECT (avg(avg_calc.member_count))::integer AS avg
           FROM ( SELECT count(*) AS member_count
                   FROM social_features.classroom_members
                  WHERE (classroom_members.is_active = true)
                  GROUP BY classroom_members.classroom_id) avg_calc) AS avg_classroom_size,
    ( SELECT count(*) AS count
           FROM educational_content.modules
          WHERE (modules.status = 'published'::educational_content.module_status)) AS total_modules,
    ( SELECT count(*) AS count
           FROM educational_content.exercises
          WHERE (exercises.is_active = true)) AS total_exercises,
    ( SELECT count(*) AS count
           FROM educational_content.assignments
          WHERE (assignments.is_published = true)) AS total_assignments,
    ( SELECT count(*) AS count
           FROM educational_content.teacher_contents
          WHERE ((teacher_contents.status)::text = 'published'::text)) AS total_teacher_content,
    ( SELECT count(*) AS count
           FROM auth_management.user_sessions
          WHERE (user_sessions.last_activity_at >= (now() - '24:00:00'::interval))) AS active_sessions_24h,
    ( SELECT count(DISTINCT user_sessions.user_id) AS count
           FROM auth_management.user_sessions
          WHERE (user_sessions.last_activity_at >= (now() - '24:00:00'::interval))) AS unique_active_users_24h,
    ( SELECT count(*) AS count
           FROM gamification_system.user_stats) AS total_gamification_users,
    ( SELECT (avg(user_stats.total_xp))::integer AS avg
           FROM gamification_system.user_stats) AS avg_user_xp,
    ( SELECT (avg(user_stats.ml_coins))::integer AS avg
           FROM gamification_system.user_stats) AS avg_user_ml_coins,
    ( SELECT sum(user_stats.total_xp) AS sum
           FROM gamification_system.user_stats) AS total_xp_system,
    ( SELECT sum(user_stats.ml_coins) AS sum
           FROM gamification_system.user_stats) AS total_ml_coins_system,
    ( SELECT count(*) AS count
           FROM system_configuration.feature_flags
          WHERE (feature_flags.is_enabled = true)) AS enabled_features_count,
    ( SELECT count(*) AS count
           FROM audit_logging.system_logs
          WHERE ((system_logs.created_at >= (now() - '01:00:00'::interval)) AND (system_logs.log_level = 'error'::text))) AS errors_last_hour
  WITH NO DATA;


ALTER MATERIALIZED VIEW admin_dashboard.system_overview_mv OWNER TO postgres;

--
-- Name: MATERIALIZED VIEW system_overview_mv; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON MATERIALIZED VIEW admin_dashboard.system_overview_mv IS 'System-wide overview statistics for admin dashboard. Refreshed periodically for performance.
Refresh with: REFRESH MATERIALIZED VIEW CONCURRENTLY admin_dashboard.system_overview_mv;';


--
-- Name: user_analytics_mv; Type: MATERIALIZED VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE MATERIALIZED VIEW admin_dashboard.user_analytics_mv AS
 SELECT p.id AS user_id,
    p.display_name,
    p.email,
    p.avatar_url,
    ur.role,
    p.tenant_id,
    p.status,
    p.created_at AS registered_at,
    COALESCE(us.total_xp, 0) AS total_xp,
    COALESCE(us.level, 1) AS current_level,
    COALESCE((us.current_rank)::text, 'ajaw'::text) AS current_rank,
    COALESCE(us.ml_coins, 0) AS ml_coins,
    COALESCE(us.ml_coins_earned_total, 0) AS ml_coins_earned,
    COALESCE(us.exercises_completed, 0) AS exercises_completed,
    COALESCE(us.modules_completed, 0) AS missions_completed,
    COALESCE(us.current_streak, 0) AS current_streak,
    COALESCE(us.max_streak, 0) AS longest_streak,
    us.last_activity_at,
    LEAST(100, ((((COALESCE(us.exercises_completed, 0) * 2) + (COALESCE(us.modules_completed, 0) * 10)) + (COALESCE(us.current_streak, 0) * 5)) / 10)) AS engagement_score,
    ( SELECT count(*) AS count
           FROM social_features.classroom_members cm
          WHERE ((cm.student_id = p.id) AND (cm.is_active = true))) AS enrolled_classrooms_count,
    ( SELECT count(*) AS count
           FROM social_features.teacher_classrooms tc
          WHERE (tc.teacher_id = p.id)) AS teaching_classrooms_count,
    ( SELECT user_sessions.last_activity_at
           FROM auth_management.user_sessions
          WHERE (user_sessions.user_id = p.id)
          ORDER BY user_sessions.last_activity_at DESC
         LIMIT 1) AS last_session_at,
    now() AS snapshot_timestamp
   FROM ((auth_management.profiles p
     LEFT JOIN auth_management.user_roles ur ON (((ur.user_id = p.id) AND (ur.is_active = true))))
     LEFT JOIN gamification_system.user_stats us ON ((us.user_id = p.id)))
  WHERE (p.status = 'active'::auth_management.user_status)
  WITH NO DATA;


ALTER MATERIALIZED VIEW admin_dashboard.user_analytics_mv OWNER TO postgres;

--
-- Name: MATERIALIZED VIEW user_analytics_mv; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON MATERIALIZED VIEW admin_dashboard.user_analytics_mv IS 'Per-user analytics including gamification stats, engagement metrics, and activity tracking.
Refresh with: REFRESH MATERIALIZED VIEW CONCURRENTLY admin_dashboard.user_analytics_mv;';


--
-- Name: user_stats_summary; Type: VIEW; Schema: admin_dashboard; Owner: postgres
--

CREATE VIEW admin_dashboard.user_stats_summary AS
 SELECT count(*) FILTER (WHERE (deleted_at IS NULL)) AS total_users,
    count(*) FILTER (WHERE (created_at >= CURRENT_DATE)) AS users_today,
    count(*) FILTER (WHERE (created_at >= (CURRENT_DATE - '7 days'::interval))) AS users_this_week,
    count(*) FILTER (WHERE (created_at >= (CURRENT_DATE - '30 days'::interval))) AS users_this_month,
    count(*) FILTER (WHERE (last_sign_in_at >= CURRENT_DATE)) AS active_users_today,
    count(*) FILTER (WHERE (last_sign_in_at >= (CURRENT_DATE - '7 days'::interval))) AS active_users_week,
    count(*) FILTER (WHERE ((role)::text = 'student'::text)) AS total_students,
    count(*) FILTER (WHERE ((role)::text = 'admin_teacher'::text)) AS total_teachers,
    count(*) FILTER (WHERE ((role)::text = 'super_admin'::text)) AS total_admins
   FROM auth.users;


ALTER VIEW admin_dashboard.user_stats_summary OWNER TO postgres;

