    CONSTRAINT chk_mod_rule_entity CHECK (((target_entity)::text = ANY ((ARRAY['content'::character varying, 'comment'::character varying, 'message'::character varying, 'post'::character varying])::text[]))),
    CONSTRAINT chk_mod_rule_severity CHECK (((severity)::text = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::text[]))),
    CONSTRAINT chk_mod_rule_type CHECK (((rule_type)::text = ANY ((ARRAY['keyword'::character varying, 'pattern'::character varying, 'length'::character varying, 'frequency'::character varying])::text[])))
);


