COMMENT ON VIEW data_warehouse.v_ml_at_risk_students IS 'Latest dropout risk for each student (last 24h)';


--
-- Name: v_ml_model_performance; Type: VIEW; Schema: data_warehouse; Owner: postgres
--

CREATE VIEW data_warehouse.v_ml_model_performance AS
 SELECT model_type,
    model_version,
    date_trunc('day'::text, created_at) AS prediction_date,
    count(*) AS total_predictions,
    count(
        CASE
            WHEN cached THEN 1
            ELSE NULL::integer
        END) AS cache_hits,
    avg(latency_ms) AS avg_latency_ms,
    avg(confidence) AS avg_confidence,
    count(
        CASE
            WHEN (validated_at IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS validated_count,
    avg(
        CASE
            WHEN prediction_accurate THEN 1.0
            ELSE 0.0
        END) AS accuracy_rate
   FROM data_warehouse.ml_prediction_logs
  GROUP BY model_type, model_version, (date_trunc('day'::text, created_at))
  ORDER BY (date_trunc('day'::text, created_at)) DESC, model_type;


ALTER VIEW data_warehouse.v_ml_model_performance OWNER TO postgres;

