-- Name: VIEW v_ml_model_performance; Type: COMMENT; Schema: data_warehouse; Owner: postgres
--

COMMENT ON VIEW data_warehouse.v_ml_model_performance IS 'Daily model performance metrics';


--
-- Name: v_student_engagement_metrics; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_engagement_metrics AS
 WITH recent_progress AS (
         SELECT fdp.student_key,
            fdp.date_key,
            dd.full_date,
            dd.day_of_week,
            dd.is_weekend,
            fdp.login_count,
            fdp.sessions_count,
            fdp.total_time_spent_seconds,
            fdp.streak_days,
            fdp.is_active_day,
            fdp.exercises_completed,
            fdp.xp_earned,
            fdp.ml_coins_earned
           FROM (data_warehouse.fact_daily_progress fdp
             JOIN data_warehouse.dim_dates dd ON ((fdp.date_key = dd.date_key)))
          WHERE (dd.full_date >= (CURRENT_DATE - '90 days'::interval))
        ), daily_aggregates AS (
         SELECT rp.student_key,
            sum(
                CASE
                    WHEN (rp.full_date >= (CURRENT_DATE - '7 days'::interval)) THEN rp.login_count
                    ELSE 0
                END) AS login_count_7d,
            sum(
                CASE
                    WHEN (rp.full_date >= (CURRENT_DATE - '30 days'::interval)) THEN rp.login_count
                    ELSE 0
                END) AS login_count_30d,
            sum(rp.login_count) AS login_count_90d,
            sum(rp.sessions_count) AS total_sessions_90d,
            avg(
                CASE
                    WHEN (rp.sessions_count > 0) THEN ((rp.total_time_spent_seconds)::double precision / (rp.sessions_count)::double precision)
                    ELSE NULL::double precision
                END) AS avg_session_duration_seconds,
            sum(rp.total_time_spent_seconds) AS total_time_spent_90d,
            max(rp.streak_days) AS max_streak_90d,
            count(*) FILTER (WHERE (rp.is_active_day = true)) AS active_days_90d,
            count(DISTINCT rp.full_date) FILTER (WHERE ((rp.is_active_day = true) AND (rp.full_date >= (CURRENT_DATE - '7 days'::interval)))) AS active_days_7d,
            count(DISTINCT rp.full_date) FILTER (WHERE ((rp.is_active_day = true) AND (rp.full_date >= (CURRENT_DATE - '30 days'::interval)))) AS active_days_30d,
            sum(rp.exercises_completed) AS exercises_completed_90d,
            ((sum(
                CASE
                    WHEN rp.is_weekend THEN rp.login_count
                    ELSE 0
                END))::double precision / (NULLIF(sum(rp.login_count), 0))::double precision) AS weekend_activity_ratio,
            mode() WITHIN GROUP (ORDER BY rp.day_of_week) FILTER (WHERE (rp.is_active_day = true)) AS most_active_day_of_week,
                CASE
                    WHEN (avg(rp.login_count) > (0)::numeric) THEN (stddev(rp.login_count) / avg(rp.login_count))
                    ELSE (1)::numeric
                END AS activity_variation_coefficient,
            sum(rp.xp_earned) AS xp_earned_90d,
            sum(rp.ml_coins_earned) AS ml_coins_earned_90d
           FROM recent_progress rp
          GROUP BY rp.student_key
        ), last_activity AS (
         SELECT recent_progress.student_key,
            max(recent_progress.full_date) AS last_activity_date,
            (CURRENT_DATE - max(recent_progress.full_date)) AS days_since_last_login
           FROM recent_progress
          WHERE (recent_progress.is_active_day = true)
          GROUP BY recent_progress.student_key
        ), current_streak AS (
         SELECT ranked.student_key,
            ranked.streak_days AS current_streak
           FROM ( SELECT rp.student_key,
                    rp.streak_days,
                    row_number() OVER (PARTITION BY rp.student_key ORDER BY rp.full_date DESC) AS rn
                   FROM recent_progress rp
                  WHERE (rp.is_active_day = true)) ranked
          WHERE (ranked.rn = 1)
        )
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.email,
    ds.current_rank,
    ds.current_level,
    COALESCE(da.login_count_7d, (0)::bigint) AS login_count_7d,
    COALESCE(da.login_count_30d, (0)::bigint) AS login_count_30d,
    COALESCE(da.login_count_90d, (0)::bigint) AS login_count_90d,
    COALESCE(da.total_sessions_90d, (0)::bigint) AS total_sessions_90d,
    COALESCE((da.avg_session_duration_seconds / (60)::double precision), (0)::double precision) AS avg_session_duration_minutes,
    COALESCE((da.total_time_spent_90d / 60), (0)::bigint) AS total_time_spent_minutes_90d,
    COALESCE(cs.current_streak, 0) AS current_streak,
    COALESCE(da.max_streak_90d, 0) AS max_streak_90d,
    COALESCE(da.active_days_7d, (0)::bigint) AS active_days_7d,
    COALESCE(da.active_days_30d, (0)::bigint) AS active_days_30d,
    COALESCE(da.active_days_90d, (0)::bigint) AS active_days_90d,
    COALESCE(la.days_since_last_login, 90) AS days_since_last_login,
    COALESCE(da.exercises_completed_90d, (0)::bigint) AS exercises_completed_90d,
    COALESCE(da.weekend_activity_ratio, (0)::double precision) AS weekend_activity_ratio,
    COALESCE(da.most_active_day_of_week, 3) AS most_active_day_of_week,
    COALESCE(((1)::numeric - da.activity_variation_coefficient), 0.5) AS activity_regularity_score,
    COALESCE(da.xp_earned_90d, (0)::bigint) AS xp_earned_90d,
    COALESCE(da.ml_coins_earned_90d, (0)::bigint) AS ml_coins_earned_90d,
        CASE
            WHEN (da.login_count_7d > 0) THEN true
            ELSE false
        END AS is_active_last_7d,
        CASE
            WHEN (da.active_days_30d > 0) THEN ((da.exercises_completed_90d)::double precision / (da.active_days_90d)::double precision)
            ELSE (0)::double precision
        END AS exercises_per_active_day,
    la.last_activity_date,
    CURRENT_TIMESTAMP AS generated_at
   FROM (((data_warehouse.dim_students ds
     LEFT JOIN daily_aggregates da ON ((ds.student_key = da.student_key)))
     LEFT JOIN last_activity la ON ((ds.student_key = la.student_key)))
     LEFT JOIN current_streak cs ON ((ds.student_key = cs.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


ALTER VIEW data_warehouse.v_student_engagement_metrics OWNER TO gamilit_user;

--
-- Name: VIEW v_student_engagement_metrics; Type: COMMENT; Schema: data_warehouse; Owner: gamilit_user
--

COMMENT ON VIEW data_warehouse.v_student_engagement_metrics IS 'Aggregated engagement metrics for ML feature engineering.
Provides pre-computed engagement features for each student including:
- Login frequency (7d, 30d, 90d)
- Session metrics (count, duration)
- Streak metrics (current, max)
- Activity patterns (weekend ratio, day preference)
- Regularity/consistency scores
Sprint 3.1 - Feature Engineering for ML Predictions';


--
-- Name: v_student_performance_metrics; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_performance_metrics AS
 WITH recent_completions AS (
         SELECT fec.student_key,
            fec.date_key,
            fec.exercise_key,
            fec.module_key,
            dd_1.full_date,
            fec.score_percentage,
            fec.time_spent_seconds,
            fec.is_passed,
            fec.is_perfect,
            fec.is_first_attempt,
            fec.hints_used,
            fec.attempt_number,
            de.difficulty_level,
            dm.module_id,
            dm.module_code
           FROM (((data_warehouse.fact_exercise_completions fec
             JOIN data_warehouse.dim_dates dd_1 ON ((fec.date_key = dd_1.date_key)))
             JOIN data_warehouse.dim_exercises de ON ((fec.exercise_key = de.exercise_key)))
             JOIN data_warehouse.dim_modules dm ON ((fec.module_key = dm.module_key)))
          WHERE (dd_1.full_date >= (CURRENT_DATE - '90 days'::interval))
        ), score_aggregates AS (
         SELECT rc.student_key,
            avg(
                CASE
                    WHEN (rc.full_date >= (CURRENT_DATE - '7 days'::interval)) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_7d,
            avg(
                CASE
                    WHEN (rc.full_date >= (CURRENT_DATE - '30 days'::interval)) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_30d,
            avg(rc.score_percentage) AS avg_score_90d,
            min(rc.score_percentage) AS min_score_90d,
            max(rc.score_percentage) AS max_score_90d,
            variance(rc.score_percentage) AS score_variance,
            stddev(rc.score_percentage) AS score_stddev,
            count(*) FILTER (WHERE rc.is_perfect) AS perfect_score_count_90d,
            avg(rc.time_spent_seconds) AS avg_time_per_exercise_seconds,
            min(rc.time_spent_seconds) AS min_time_per_exercise_seconds,
            max(rc.time_spent_seconds) AS max_time_per_exercise_seconds
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), completion_rates AS (
         SELECT rc.student_key,
            count(*) FILTER (WHERE rc.is_passed) AS exercises_completed_90d,
            count(*) AS exercises_attempted_90d,
            count(*) FILTER (WHERE (NOT rc.is_passed)) AS exercises_failed_90d,
            (((count(*) FILTER (WHERE (rc.is_passed AND (rc.full_date >= (CURRENT_DATE - '7 days'::interval)))))::double precision / (NULLIF(count(*) FILTER (WHERE (rc.full_date >= (CURRENT_DATE - '7 days'::interval))), 0))::double precision) * (100)::double precision) AS completion_rate_7d,
            (((count(*) FILTER (WHERE (rc.is_passed AND (rc.full_date >= (CURRENT_DATE - '30 days'::interval)))))::double precision / (NULLIF(count(*) FILTER (WHERE (rc.full_date >= (CURRENT_DATE - '30 days'::interval))), 0))::double precision) * (100)::double precision) AS completion_rate_30d,
            (((count(*) FILTER (WHERE rc.is_passed))::double precision / (NULLIF(count(*), 0))::double precision) * (100)::double precision) AS completion_rate_90d,
            (((count(*) FILTER (WHERE (rc.is_first_attempt AND rc.is_passed)))::double precision / (NULLIF(count(*) FILTER (WHERE rc.is_first_attempt), 0))::double precision) * (100)::double precision) AS first_attempt_success_rate,
            ((count(*) FILTER (WHERE (rc.hints_used > 0)))::double precision / (NULLIF(count(*), 0))::double precision) AS hints_usage_rate,
            avg(rc.hints_used) AS avg_hints_per_exercise,
            avg(rc.attempt_number) AS avg_attempts_per_exercise
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), difficulty_distribution AS (
         SELECT rc.student_key,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'easy'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_easy_ratio,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'medium'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_medium_ratio,
            ((count(*) FILTER (WHERE (rc.difficulty_level = 'hard'::text)))::double precision / (NULLIF(count(*), 0))::double precision) AS difficulty_hard_ratio,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'easy'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_easy,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'medium'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_medium,
            avg(
                CASE
                    WHEN (rc.difficulty_level = 'hard'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS avg_score_hard
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), module_progress AS (
         SELECT rc.student_key,
            max(
                CASE
                    WHEN (rc.module_code = 'M1'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_1_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M2'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_2_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M3'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_3_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M4'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_4_best_score,
            max(
                CASE
                    WHEN (rc.module_code = 'M5'::text) THEN rc.score_percentage
                    ELSE NULL::numeric
                END) AS module_5_best_score,
            count(DISTINCT rc.module_key) AS modules_attempted
           FROM recent_completions rc
          GROUP BY rc.student_key
        ), improvement_trend AS (
         SELECT weekly_scores.student_key,
            regr_slope((weekly_scores.avg_score)::double precision, (weekly_scores.week_num)::double precision) AS improvement_slope
           FROM ( SELECT rc.student_key,
                    date_trunc('week'::text, (rc.full_date)::timestamp with time zone) AS week_start,
                    (EXTRACT(week FROM rc.full_date) - EXTRACT(week FROM (CURRENT_DATE - '90 days'::interval))) AS week_num,
                    avg(rc.score_percentage) AS avg_score
                   FROM recent_completions rc
                  GROUP BY rc.student_key, (date_trunc('week'::text, (rc.full_date)::timestamp with time zone)), (EXTRACT(week FROM rc.full_date))) weekly_scores
          GROUP BY weekly_scores.student_key
        )
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.current_rank,
    ds.current_level,
    ds.total_xp,
    COALESCE(sa.avg_score_7d, (0)::numeric) AS avg_score_7d,
    COALESCE(sa.avg_score_30d, (0)::numeric) AS avg_score_30d,
    COALESCE(sa.avg_score_90d, (0)::numeric) AS avg_score_90d,
    COALESCE(sa.min_score_90d, (0)::numeric) AS min_score_90d,
    COALESCE(sa.max_score_90d, (0)::numeric) AS max_score_90d,
    COALESCE(sa.score_variance, (0)::numeric) AS score_variance,
    COALESCE(sa.score_stddev, (0)::numeric) AS score_stddev,
    COALESCE(sa.perfect_score_count_90d, (0)::bigint) AS perfect_score_count,
    COALESCE(sa.avg_time_per_exercise_seconds, (0)::numeric) AS avg_time_per_exercise_seconds,
    COALESCE(cr.exercises_completed_90d, (0)::bigint) AS exercises_completed_total,
    COALESCE(cr.exercises_attempted_90d, (0)::bigint) AS exercises_attempted_total,
    COALESCE(cr.exercises_failed_90d, (0)::bigint) AS exercises_failed_total,
    COALESCE(cr.completion_rate_7d, (0)::double precision) AS completion_rate_7d,
    COALESCE(cr.completion_rate_30d, (0)::double precision) AS completion_rate_30d,
    COALESCE(cr.completion_rate_90d, (0)::double precision) AS completion_rate_90d,
    COALESCE(cr.first_attempt_success_rate, (0)::double precision) AS first_attempt_success_rate,
    COALESCE(cr.hints_usage_rate, (0)::double precision) AS hints_usage_rate,
    COALESCE(cr.avg_hints_per_exercise, (0)::numeric) AS avg_hints_per_exercise,
    COALESCE(cr.avg_attempts_per_exercise, (1)::numeric) AS avg_attempts_per_exercise,
    COALESCE(dd.difficulty_easy_ratio, (0.33)::double precision) AS difficulty_easy_ratio,
    COALESCE(dd.difficulty_medium_ratio, (0.33)::double precision) AS difficulty_medium_ratio,
    COALESCE(dd.difficulty_hard_ratio, (0.33)::double precision) AS difficulty_hard_ratio,
    COALESCE(dd.avg_score_easy, (0)::numeric) AS avg_score_easy,
    COALESCE(dd.avg_score_medium, (0)::numeric) AS avg_score_medium,
    COALESCE(dd.avg_score_hard, (0)::numeric) AS avg_score_hard,
    COALESCE(mp.module_1_best_score, (0)::numeric) AS module_1_progress,
    COALESCE(mp.module_2_best_score, (0)::numeric) AS module_2_progress,
    COALESCE(mp.module_3_best_score, (0)::numeric) AS module_3_progress,
    COALESCE(mp.module_4_best_score, (0)::numeric) AS module_4_progress,
    COALESCE(mp.module_5_best_score, (0)::numeric) AS module_5_progress,
    COALESCE(mp.modules_attempted, (0)::bigint) AS modules_attempted,
    COALESCE(it.improvement_slope, (0)::double precision) AS improvement_trend,
        CASE
            WHEN (COALESCE(sa.score_variance, (0)::numeric) < (100)::numeric) THEN 'consistent'::text
            WHEN (COALESCE(sa.score_variance, (0)::numeric) < (300)::numeric) THEN 'moderate'::text
            ELSE 'variable'::text
        END AS score_consistency_category,
        CASE
            WHEN (COALESCE(it.improvement_slope, (0)::double precision) > (1)::double precision) THEN 'improving'::text
            WHEN (COALESCE(it.improvement_slope, (0)::double precision) < ('-1'::integer)::double precision) THEN 'declining'::text
            ELSE 'stable'::text
        END AS performance_trend_category,
    CURRENT_TIMESTAMP AS generated_at
   FROM (((((data_warehouse.dim_students ds
     LEFT JOIN score_aggregates sa ON ((ds.student_key = sa.student_key)))
     LEFT JOIN completion_rates cr ON ((ds.student_key = cr.student_key)))
     LEFT JOIN difficulty_distribution dd ON ((ds.student_key = dd.student_key)))
     LEFT JOIN module_progress mp ON ((ds.student_key = mp.student_key)))
     LEFT JOIN improvement_trend it ON ((ds.student_key = it.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


ALTER VIEW data_warehouse.v_student_performance_metrics OWNER TO gamilit_user;

--
-- Name: VIEW v_student_performance_metrics; Type: COMMENT; Schema: data_warehouse; Owner: gamilit_user
--

COMMENT ON VIEW data_warehouse.v_student_performance_metrics IS 'Aggregated performance metrics for ML feature engineering.
Provides pre-computed performance features for each student including:
- Score metrics (avg, min, max, variance) by time period
- Completion rates (7d, 30d, 90d)
- First attempt success rate
- Hints and retry behavior
- Difficulty distribution and scores by difficulty
- Module progress
- Improvement trend (slope)
Sprint 3.1 - Feature Engineering for ML Predictions';


--
-- Name: v_student_feature_base; Type: VIEW; Schema: data_warehouse; Owner: gamilit_user
--

CREATE VIEW data_warehouse.v_student_feature_base AS
 SELECT ds.student_key,
    ds.student_id,
    ds.display_name,
    ds.email,
    ds.current_rank,
    ds.current_level,
    ds.total_xp,
    ds.ml_coins_balance,
    ds.grade_level,
    ds.school_id,
    ds.school_name,
    ds.status,
    ds.registration_date,
    ds.first_activity_date,
    ds.last_activity_date,
    (CURRENT_DATE - ds.registration_date) AS days_since_registration,
    (CURRENT_DATE - COALESCE(ds.first_activity_date, ds.registration_date)) AS days_since_first_activity,
        CASE ds.current_rank
            WHEN 'Alumno'::text THEN 1
            WHEN 'Aprendiz'::text THEN 2
            WHEN 'Estudiante'::text THEN 3
            WHEN 'Erudito'::text THEN 4
            WHEN 'Explorador'::text THEN 5
            WHEN 'Investigador'::text THEN 6
            WHEN 'Artesano'::text THEN 7
            WHEN 'Creador'::text THEN 8
            WHEN 'Innovador'::text THEN 9
            WHEN 'Experto'::text THEN 10
            WHEN 'Maestro'::text THEN 11
            WHEN 'Sabio'::text THEN 12
            WHEN 'Guardian'::text THEN 13
            ELSE 1
        END AS current_rank_level,
        CASE
            WHEN ((ds.display_name IS NOT NULL) AND (ds.school_id IS NOT NULL)) THEN 100
            WHEN (ds.display_name IS NOT NULL) THEN 60
            ELSE 20
        END AS profile_completeness,
    (ds.school_id IS NOT NULL) AS has_school_association,
    COALESCE(em.login_count_7d, (0)::bigint) AS login_frequency_7d,
    COALESCE(em.login_count_30d, (0)::bigint) AS login_frequency_30d,
    COALESCE(em.login_count_90d, (0)::bigint) AS login_frequency_90d,
    COALESCE(em.avg_session_duration_minutes, (0)::double precision) AS avg_session_duration,
    COALESCE(em.total_time_spent_minutes_90d, (0)::bigint) AS total_session_time_30d,
    COALESCE(em.current_streak, 0) AS streak_current,
    COALESCE(em.max_streak_90d, 0) AS streak_max,
    COALESCE(em.days_since_last_login, 90) AS days_since_last_login,
    COALESCE(em.weekend_activity_ratio, (0)::double precision) AS weekend_activity_ratio,
    COALESCE(em.total_sessions_90d, (0)::bigint) AS sessions_count_30d,
    COALESCE(em.exercises_per_active_day, (0)::double precision) AS avg_activities_per_session,
    COALESCE(em.is_active_last_7d, false) AS is_active_last_7d,
    COALESCE(em.activity_regularity_score, 0.5) AS activity_regularity_score,
    (em.activity_regularity_score > 0.5) AS has_consistent_schedule,
        CASE em.most_active_day_of_week
            WHEN 0 THEN 'Sunday'::text
            WHEN 1 THEN 'Monday'::text
            WHEN 2 THEN 'Tuesday'::text
            WHEN 3 THEN 'Wednesday'::text
            WHEN 4 THEN 'Thursday'::text
            WHEN 5 THEN 'Friday'::text
            WHEN 6 THEN 'Saturday'::text
            ELSE 'Unknown'::text
        END AS most_active_day_name,
    COALESCE(pm.avg_score_7d, (0)::numeric) AS avg_score_7d,
    COALESCE(pm.avg_score_30d, (0)::numeric) AS avg_score_30d,
    COALESCE(pm.avg_score_90d, (0)::numeric) AS avg_score_all,
    COALESCE(pm.completion_rate_7d, (0)::double precision) AS completion_rate_7d,
    COALESCE(pm.completion_rate_30d, (0)::double precision) AS completion_rate_30d,
    COALESCE(pm.exercises_completed_total, (0)::bigint) AS exercises_completed_total,
    COALESCE(pm.exercises_attempted_total, (0)::bigint) AS exercises_attempted_total,
    COALESCE(pm.exercises_failed_total, (0)::bigint) AS exercises_failed_total,
    COALESCE(pm.avg_time_per_exercise_seconds, (0)::numeric) AS avg_time_per_exercise,
    COALESCE(pm.perfect_score_count, (0)::bigint) AS perfect_score_count,
    COALESCE(pm.difficulty_easy_ratio, (0.33)::double precision) AS difficulty_easy_ratio,
    COALESCE(pm.difficulty_medium_ratio, (0.33)::double precision) AS difficulty_medium_ratio,
    COALESCE(pm.difficulty_hard_ratio, (0.33)::double precision) AS difficulty_hard_ratio,
    COALESCE(pm.score_variance, (0)::numeric) AS score_variance,
    COALESCE(pm.improvement_trend, (0)::double precision) AS improvement_trend,
    COALESCE(pm.hints_usage_rate, (0)::double precision) AS hints_usage_rate,
    COALESCE(pm.first_attempt_success_rate, (0)::double precision) AS first_attempt_success_rate,
    COALESCE(pm.module_1_progress, (0)::numeric) AS module_progress_m1,
    COALESCE(pm.module_2_progress, (0)::numeric) AS module_progress_m2,
    COALESCE(pm.module_3_progress, (0)::numeric) AS module_progress_m3,
    COALESCE(pm.module_4_progress, (0)::numeric) AS module_progress_m4,
    COALESCE(pm.module_5_progress, (0)::numeric) AS module_progress_m5,
        CASE
            WHEN (COALESCE(em.days_since_last_login, 90) > 14) THEN true
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) < 3) THEN true
            WHEN ((COALESCE(pm.avg_score_30d, (0)::numeric) < (40)::numeric) AND (COALESCE(pm.exercises_attempted_total, (0)::bigint) > 10)) THEN true
            ELSE false
        END AS high_dropout_risk_indicator,
        CASE
            WHEN ((COALESCE(em.login_count_7d, (0)::bigint) >= 5) AND (COALESCE(em.current_streak, 0) >= 3)) THEN 'very_high'::text
            WHEN (COALESCE(em.login_count_7d, (0)::bigint) >= 3) THEN 'high'::text
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) >= 5) THEN 'moderate'::text
            WHEN (COALESCE(em.login_count_30d, (0)::bigint) >= 1) THEN 'low'::text
            ELSE 'disengaged'::text
        END AS engagement_level,
        CASE
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (80)::numeric) THEN 'excellent'::text
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (60)::numeric) THEN 'good'::text
            WHEN (COALESCE(pm.avg_score_30d, (0)::numeric) >= (40)::numeric) THEN 'needs_improvement'::text
            ELSE 'at_risk'::text
        END AS performance_level,
    CURRENT_TIMESTAMP AS generated_at,
    '1.0.0'::text AS feature_version
   FROM ((data_warehouse.dim_students ds
     LEFT JOIN data_warehouse.v_student_engagement_metrics em ON ((ds.student_key = em.student_key)))
     LEFT JOIN data_warehouse.v_student_performance_metrics pm ON ((ds.student_key = pm.student_key)))
  WHERE ((ds.is_current = true) AND (ds.role = 'student'::text));


ALTER VIEW data_warehouse.v_student_feature_base OWNER TO gamilit_user;

--
-- Name: VIEW v_student_feature_base; Type: COMMENT; Schema: data_warehouse; Owner: gamilit_user
--

COMMENT ON VIEW data_warehouse.v_student_feature_base IS 'Combined feature base view for ML predictions.
Joins student profile, engagement metrics, and performance metrics into a single
feature vector suitable for ML model input.
Includes:
- Student profile features (45 features)
- Engagement features (login frequency, streaks, session duration)
- Performance features (scores, completion rates, trends)
- Computed risk indicators and classifications
Sprint 3.1 - Feature Engineering for ML Predictions';


--
-- Name: assessment_rubrics; Type: TABLE; Schema: educational_content; Owner: gamilit_user
--

CREATE TABLE educational_content.assessment_rubrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    exercise_id uuid,
    module_id uuid,
    name text NOT NULL,
    description text,
    assessment_type text,
    criteria jsonb DEFAULT '{"criteria_1": {"name": "Comprehension", "levels": {"good": {"points": 75, "description": "Good comprehension"}, "basic": {"points": 50, "description": "Basic comprehension"}, "excellent": {"points": 100, "description": "Full comprehension"}, "insufficient": {"points": 25, "description": "Limited comprehension"}}, "weight": 40}}'::jsonb,
    scoring_scale jsonb DEFAULT '{"max": 100, "min": 0, "passing": 70}'::jsonb,
    weight_percentage numeric(5,2) DEFAULT 100.00,
    is_active boolean DEFAULT true,
    allow_resubmission boolean DEFAULT true,
    feedback_template text,
    auto_feedback_enabled boolean DEFAULT true,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_by uuid,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT assessment_rubrics_assessment_type_check CHECK ((assessment_type = ANY (ARRAY['automatic'::text, 'manual'::text, 'hybrid'::text, 'peer_review'::text]))),
    CONSTRAINT assessment_rubrics_weight_percentage_check CHECK (((weight_percentage > (0)::numeric) AND (weight_percentage <= (100)::numeric))),
    CONSTRAINT rubric_reference_check CHECK ((((exercise_id IS NOT NULL) AND (module_id IS NULL)) OR ((exercise_id IS NULL) AND (module_id IS NOT NULL))))
);

