    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_id uuid NOT NULL,
    student_id uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    submitted_at timestamp with time zone,
    submission_data jsonb DEFAULT '{}'::jsonb,
    submission_url text,
    submission_files jsonb DEFAULT '[]'::jsonb,
    score numeric(5,2),
    max_score numeric(5,2),
    percentage numeric(5,2),
    feedback text,
    graded_by uuid,
    graded_at timestamp with time zone,
    status character varying(50) DEFAULT 'assigned'::character varying,
    attempt_number integer DEFAULT 1,
    max_attempts integer DEFAULT 1,
    is_late boolean DEFAULT false,
    late_penalty_applied numeric(5,2) DEFAULT 0,
    rubric_scores jsonb DEFAULT '{}'::jsonb,
    teacher_notes text,
    flagged_for_review boolean DEFAULT false,
    flag_reason text,
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT assignment_students_attempt_positive CHECK (((attempt_number > 0) AND (attempt_number <= max_attempts))),
    CONSTRAINT assignment_students_percentage_valid CHECK (((percentage IS NULL) OR ((percentage >= (0)::numeric) AND (percentage <= (100)::numeric)))),
    CONSTRAINT assignment_students_score_valid CHECK (((score IS NULL) OR ((score >= (0)::numeric) AND (score <= max_score)))),
    CONSTRAINT assignment_students_status_valid CHECK (((status)::text = ANY ((ARRAY['assigned'::character varying, 'in_progress'::character varying, 'submitted'::character varying, 'graded'::character varying, 'returned'::character varying, 'late'::character varying, 'excused'::character varying])::text[])))
);


