--
-- Name: mv_mechanic_leaderboard; Type: MATERIALIZED VIEW; Schema: gamification_system; Owner: postgres
--

CREATE MATERIALIZED VIEW gamification_system.mv_mechanic_leaderboard AS
 SELECT m.mission_type AS mechanic_id,
    m.mission_type AS mechanic_name,
    row_number() OVER (PARTITION BY m.mission_type ORDER BY us.total_xp DESC) AS rank,
    p.id AS user_id,
    p.full_name,
    p.avatar_url,
    ur.current_rank,
    us.total_xp AS user_xp,
    us.level,
    us.ml_coins,
    count(DISTINCT sm.id) AS missions_scheduled
   FROM ((((gamification_system.missions m
     CROSS JOIN auth_management.profiles p)
     JOIN gamification_system.user_stats us ON ((p.id = us.user_id)))
     LEFT JOIN gamification_system.user_ranks ur ON (((p.id = ur.user_id) AND (ur.is_current = true))))
     LEFT JOIN progress_tracking.scheduled_missions sm ON ((m.id = sm.mission_id)))
  WHERE ((p.role = 'student'::auth_management.gamilit_role) AND (p.status = 'active'::auth_management.user_status))
  GROUP BY m.mission_type, p.id, p.full_name, p.avatar_url, ur.current_rank, us.total_xp, us.level, us.ml_coins
 HAVING (us.total_xp > 0)
  ORDER BY m.mission_type, us.total_xp DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW gamification_system.mv_mechanic_leaderboard OWNER TO postgres;

--
-- Name: mv_weekly_leaderboard; Type: MATERIALIZED VIEW; Schema: gamification_system; Owner: postgres
--

CREATE MATERIALIZED VIEW gamification_system.mv_weekly_leaderboard AS
 SELECT row_number() OVER (ORDER BY us.weekly_xp DESC) AS rank,
    p.id AS user_id,
    p.full_name,
    p.avatar_url,
    ur.current_rank,
    us.weekly_xp,
    us.weekly_exercises AS activities_completed,
    us.level,
    us.ml_coins
   FROM ((auth_management.profiles p
     JOIN gamification_system.user_stats us ON ((p.id = us.user_id)))
     LEFT JOIN gamification_system.user_ranks ur ON (((p.id = ur.user_id) AND (ur.is_current = true))))
  WHERE ((p.role = 'student'::auth_management.gamilit_role) AND (p.status = 'active'::auth_management.user_status) AND (us.weekly_xp > 0))
  ORDER BY us.weekly_xp DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW gamification_system.mv_weekly_leaderboard OWNER TO postgres;

