--
-- Name: classroom_students_metrics; Type: VIEW; Schema: progress_tracking; Owner: postgres
--

CREATE VIEW progress_tracking.classroom_students_metrics AS
 SELECT cm.classroom_id,
    c.name AS classroom_name,
    cm.student_id,
    p.display_name AS student_name,
    p.email AS student_email,
    cm.enrollment_date,
    cm.status AS enrollment_status,
    COALESCE(us.total_xp, 0) AS total_xp,
    COALESCE(us.level, 1) AS current_level,
    COALESCE((us.current_rank)::text, 'ajaw'::text) AS current_rank,
    COALESCE(us.ml_coins, 0) AS ml_coins,
    COALESCE(us.exercises_completed, 0) AS exercises_completed,
    COALESCE(us.modules_completed, 0) AS modules_completed,
    COALESCE(us.total_score, 0) AS total_score,
    COALESCE(us.current_streak, 0) AS current_streak,
    COALESCE(us.max_streak, 0) AS max_streak,
    COALESCE(us.days_active_total, 0) AS days_active,
    us.last_activity_at,
    LEAST(100, (((((COALESCE(us.exercises_completed, 0) * 2) + (COALESCE(us.modules_completed, 0) * 10)) + (COALESCE(us.current_streak, 0) * 5)) + COALESCE(us.days_active_total, 0)) / 10)) AS engagement_score,
    cm.final_grade,
    cm.attendance_percentage,
    cm.is_active AS is_active_in_classroom
   FROM (((social_features.classroom_members cm
     JOIN social_features.classrooms c ON ((c.id = cm.classroom_id)))
     JOIN auth_management.profiles p ON ((p.id = cm.student_id)))
     LEFT JOIN gamification_system.user_stats us ON ((us.user_id = cm.student_id)))
  WHERE (cm.is_active = true)
  ORDER BY c.name, us.total_xp DESC NULLS LAST;


ALTER VIEW progress_tracking.classroom_students_metrics OWNER TO postgres;

--
-- Name: VIEW classroom_students_metrics; Type: COMMENT; Schema: progress_tracking; Owner: postgres
--

COMMENT ON VIEW progress_tracking.classroom_students_metrics IS 'Comprehensive view of all students in classrooms with their metrics, progress, and engagement scores.
Useful for teacher dashboards and student progress tracking.';


