    CONSTRAINT teacher_interventions_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'rescheduled'::text]))),
    CONSTRAINT teacher_interventions_type_check CHECK ((intervention_type = ANY (ARRAY['one_on_one_session'::text, 'parent_contact'::text, 'resource_assignment'::text, 'peer_tutoring'::text, 'accommodation'::text, 'referral'::text, 'behavior_plan'::text, 'progress_check'::text, 'encouragement'::text, 'schedule_adjustment'::text, 'other'::text])))
);


