--
-- Name: classroom_progress_overview; Type: VIEW; Schema: social_features; Owner: postgres
--

CREATE VIEW social_features.classroom_progress_overview AS
 SELECT c.id AS classroom_id,
    c.name AS classroom_name,
    c.teacher_id,
    count(DISTINCT cm.student_id) FILTER (WHERE (cm.status = 'active'::text)) AS total_students,
    count(DISTINCT mp.user_id) FILTER (WHERE (mp.status = 'completed'::progress_tracking.progress_status)) AS students_completed,
    COALESCE(round(avg(mp.progress_percentage), 2), (0)::numeric) AS avg_progress,
    COALESCE(round(avg(mp.average_score), 2), (0)::numeric) AS avg_score,
    count(DISTINCT sia.id) FILTER (WHERE (sia.status = 'active'::text)) AS pending_alerts,
    count(DISTINCT sia.id) FILTER (WHERE (sia.status = 'acknowledged'::text)) AS acknowledged_alerts,
    count(DISTINCT es.id) FILTER (WHERE (es.status = 'pending_review'::text)) AS pending_reviews,
    count(DISTINCT es.id) AS total_submissions,
    max(es.submitted_at) AS last_activity,
    count(DISTINCT mp.module_id) FILTER (WHERE (mp.status = 'completed'::progress_tracking.progress_status)) AS modules_completed,
    count(DISTINCT mp.module_id) AS modules_started,
    c.created_at AS classroom_created_at,
    c.updated_at AS classroom_updated_at
   FROM ((((social_features.classrooms c
     LEFT JOIN social_features.classroom_members cm ON (((c.id = cm.classroom_id) AND (cm.status = 'active'::text))))
     LEFT JOIN progress_tracking.module_progress mp ON ((cm.student_id = mp.user_id)))
     LEFT JOIN progress_tracking.student_intervention_alerts sia ON (((cm.student_id = sia.student_id) AND (sia.classroom_id = c.id))))
     LEFT JOIN progress_tracking.exercise_submissions es ON ((cm.student_id = es.user_id)))
  WHERE (c.is_deleted = false)
  GROUP BY c.id, c.name, c.teacher_id, c.created_at, c.updated_at;


ALTER VIEW social_features.classroom_progress_overview OWNER TO postgres;

--
-- Name: VIEW classroom_progress_overview; Type: COMMENT; Schema: social_features; Owner: postgres
--

COMMENT ON VIEW social_features.classroom_progress_overview IS 'Teacher Portal view for classroom progress monitoring.

Columns:
  - classroom_id/name: Classroom identification
  - teacher_id: Owner teacher
  - total_students: Active students in classroom
  - students_completed: Students who completed at least one module
  - avg_progress: Average progress percentage (0-100)
  - avg_score: Average score across all modules
  - pending_alerts: Count of pending intervention alerts
  - acknowledged_alerts: Count of acknowledged alerts
  - pending_reviews: Submissions needing manual review
  - total_submissions: Total exercise submissions
  - last_activity: Most recent submission timestamp
  - modules_completed/started: Module completion stats

Usage:
  -- Get all classrooms for a teacher
  SELECT * FROM social_features.classroom_progress_overview
  WHERE teacher_id = :teacher_id;

  -- Find classrooms needing attention
  SELECT * FROM social_features.classroom_progress_overview
  WHERE pending_alerts > 0 OR pending_reviews > 5
  ORDER BY pending_alerts DESC;

Created: 2025-12-18 (P1-03 Teacher Portal Analysis)';


