    CONSTRAINT guild_missions_reward_xp_check CHECK ((reward_xp > 0)),
    CONSTRAINT guild_missions_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'completed'::character varying, 'expired'::character varying, 'cancelled'::character varying])::text[]))),
