COMMENT ON COLUMN system_configuration.rate_limits.description IS 'Descripción del propósito de este límite';


--
-- Name: COLUMN rate_limits.metadata; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.rate_limits.metadata IS 'Metadatos adicionales en formato JSON. Puede incluir:
- error_message: Mensaje personalizado al exceder límite
- retry_after_strategy: Estrategia para Retry-After header
- exemptions: Lista de IPs o usuarios exentos';


--
-- Name: system_settings; Type: TABLE; Schema: system_configuration; Owner: gamilit_user
--

CREATE TABLE system_configuration.system_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    setting_key text NOT NULL,
    setting_category text,
    setting_subcategory text,
    setting_value text NOT NULL,
    value_type text DEFAULT 'string'::text,
    default_value text,
    display_name text,
    description text,
    help_text text,
    is_public boolean DEFAULT false,
    is_readonly boolean DEFAULT false,
    is_system boolean DEFAULT false,
    requires_restart boolean DEFAULT false,
    validation_rules jsonb DEFAULT '{}'::jsonb,
    allowed_values text[],
    min_value numeric,
    max_value numeric,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    updated_at timestamp with time zone DEFAULT gamilit.now_mexico(),
    CONSTRAINT system_settings_setting_category_check CHECK ((setting_category = ANY (ARRAY['general'::text, 'gamification'::text, 'security'::text, 'email'::text, 'storage'::text, 'analytics'::text, 'integrations'::text]))),
    CONSTRAINT system_settings_value_type_check CHECK ((value_type = ANY (ARRAY['string'::text, 'number'::text, 'boolean'::text, 'json'::text, 'array'::text])))
);


ALTER TABLE system_configuration.system_settings OWNER TO gamilit_user;

--
-- Name: TABLE system_settings; Type: COMMENT; Schema: system_configuration; Owner: gamilit_user
--

COMMENT ON TABLE system_configuration.system_settings IS 'Configuración global de la plataforma';


--
-- Name: COLUMN system_settings.setting_key; Type: COMMENT; Schema: system_configuration; Owner: gamilit_user
--

COMMENT ON COLUMN system_configuration.system_settings.setting_key IS 'Clave única del setting (ej: "ml_coins_welcome_bonus")';


--
-- Name: COLUMN system_settings.is_system; Type: COMMENT; Schema: system_configuration; Owner: gamilit_user
--

COMMENT ON COLUMN system_configuration.system_settings.is_system IS 'Si es true, no puede ser modificado por usuarios';


--
-- Name: tenant_configurations; Type: TABLE; Schema: system_configuration; Owner: postgres
--

CREATE TABLE system_configuration.tenant_configurations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    config_key character varying(100) NOT NULL,
    config_value jsonb NOT NULL,
    config_type character varying(50) NOT NULL,
    is_overridable boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT tenant_configurations_config_type_check CHECK (((config_type)::text = ANY ((ARRAY['branding'::character varying, 'features'::character varying, 'limits'::character varying, 'permissions'::character varying, 'integrations'::character varying, 'other'::character varying])::text[])))
);


ALTER TABLE system_configuration.tenant_configurations OWNER TO postgres;

--
-- Name: TABLE tenant_configurations; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON TABLE system_configuration.tenant_configurations IS 'Tenant-specific configurations for multi-tenancy (EXT-008)';


--
-- Name: COLUMN tenant_configurations.config_key; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.tenant_configurations.config_key IS 'Configuration key (e.g., "primary_color", "max_users", "allowed_modules")';


--
-- Name: COLUMN tenant_configurations.config_value; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.tenant_configurations.config_value IS 'Configuration value as JSONB';


--
-- Name: COLUMN tenant_configurations.config_type; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.tenant_configurations.config_type IS 'Type: branding, features, limits, permissions, integrations, other';


--
-- Name: COLUMN tenant_configurations.is_overridable; Type: COMMENT; Schema: system_configuration; Owner: postgres
--

COMMENT ON COLUMN system_configuration.tenant_configurations.is_overridable IS 'Whether tenant can override this configuration';


