--
-- Name: exercise_submissions trg_module_progress_complete; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_module_progress_complete AFTER UPDATE ON progress_tracking.exercise_submissions FOR EACH ROW WHEN ((((old.status IS DISTINCT FROM new.status) AND (new.status = ANY (ARRAY['graded'::text, 'reviewed'::text]))) OR ((old.score IS DISTINCT FROM new.score) AND (new.status = ANY (ARRAY['graded'::text, 'reviewed'::text]))))) EXECUTE FUNCTION progress_tracking.update_module_progress_complete();


--
-- Name: TRIGGER trg_module_progress_complete ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_module_progress_complete ON progress_tracking.exercise_submissions IS 'Trigger CONSOLIDADO que actualiza module_progress (progress + average_score) en una sola operacion. Reemplaza triggers 27 y 33. Reduccion de latencia: ~30-50ms por submission. Creado: TASK-2026-02-02-IMPLEMENTAR-OPTIMIZACION-TRIGGERS';


