--
-- Name: exercise_submissions trg_update_missions_on_submission; Type: TRIGGER; Schema: progress_tracking; Owner: gamilit_user
--

CREATE TRIGGER trg_update_missions_on_submission AFTER UPDATE ON progress_tracking.exercise_submissions FOR EACH ROW WHEN (((new.status = ANY (ARRAY['graded'::text, 'reviewed'::text])) AND (new.is_correct = true) AND ((old.status IS DISTINCT FROM new.status) OR (old.is_correct IS DISTINCT FROM new.is_correct)))) EXECUTE FUNCTION gamilit.trigger_missions_on_exercise_complete();


--
-- Name: TRIGGER trg_update_missions_on_submission ON exercise_submissions; Type: COMMENT; Schema: progress_tracking; Owner: gamilit_user
--

COMMENT ON TRIGGER trg_update_missions_on_submission ON progress_tracking.exercise_submissions IS 'Actualiza el progreso de misiones diarias/semanales cuando se califica un exercise_submission como correcto. Complementa el trigger de exercise_attempts para cubrir ejercicios con revisión manual. Usa la funcion wrapper trigger_missions_on_exercise_complete() (unificada 2025-12-29).';


