-- Name: admin_reports; Type: ROW SECURITY; Schema: admin_dashboard; Owner: postgres
--

ALTER TABLE admin_dashboard.admin_reports ENABLE ROW LEVEL SECURITY;

--
-- Name: admin_reports admin_reports_admin_all; Type: POLICY; Schema: admin_dashboard; Owner: postgres
--

CREATE POLICY admin_reports_admin_all ON admin_dashboard.admin_reports USING ((gamilit.is_admin() OR gamilit.is_super_admin()));


--
-- Name: POLICY admin_reports_admin_all ON admin_reports; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON POLICY admin_reports_admin_all ON admin_dashboard.admin_reports IS 'Admins tienen acceso completo a reportes administrativos';


--
-- Name: admin_reports admin_reports_insert_own; Type: POLICY; Schema: admin_dashboard; Owner: postgres
--

CREATE POLICY admin_reports_insert_own ON admin_dashboard.admin_reports FOR INSERT WITH CHECK ((requested_by = gamilit.get_current_user_id()));


--
-- Name: POLICY admin_reports_insert_own ON admin_reports; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON POLICY admin_reports_insert_own ON admin_dashboard.admin_reports IS 'Usuarios pueden crear reportes a su nombre';


--
-- Name: admin_reports admin_reports_read_own; Type: POLICY; Schema: admin_dashboard; Owner: postgres
--

CREATE POLICY admin_reports_read_own ON admin_dashboard.admin_reports FOR SELECT USING ((requested_by = gamilit.get_current_user_id()));


--
-- Name: POLICY admin_reports_read_own ON admin_reports; Type: COMMENT; Schema: admin_dashboard; Owner: postgres
--

COMMENT ON POLICY admin_reports_read_own ON admin_dashboard.admin_reports IS 'Usuarios pueden leer reportes que ellos solicitaron';


