-- Name: manual_reviews admin_view_tenant_reviews; Type: POLICY; Schema: progress_tracking; Owner: postgres
--

CREATE POLICY admin_view_tenant_reviews ON progress_tracking.manual_reviews FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM ((progress_tracking.exercise_submissions es
     JOIN auth_management.profiles p ON ((es.user_id = p.id)))
     JOIN auth_management.profiles admin_profile ON ((admin_profile.id = gamilit.get_current_user_id())))
  WHERE ((es.id = manual_reviews.submission_id) AND (p.tenant_id = admin_profile.tenant_id) AND (admin_profile.role = ANY (ARRAY['admin_teacher'::auth_management.gamilit_role, 'super_admin'::auth_management.gamilit_role]))))));


