   FROM (auth_management.profiles p
     JOIN auth_management.user_roles ur ON ((p.id = ur.user_id)))
  WHERE ((p.id = auth.uid()) AND (ur.role = ANY (ARRAY['admin_teacher'::auth_management.gamilit_role, 'super_admin'::auth_management.gamilit_role]))))));


--
-- Name: challenge_participants challenge_participants_delete_own; Type: POLICY; Schema: social_features; Owner: postgres
--

CREATE POLICY challenge_participants_delete_own ON social_features.challenge_participants FOR DELETE USING ((((user_id = (current_setting('app.current_user_id'::text, true))::uuid) AND (EXISTS ( SELECT 1
   FROM social_features.peer_challenges pc
  WHERE ((pc.id = challenge_participants.challenge_id) AND (pc.status = ANY (ARRAY['open'::text, 'full'::text])))))) OR (EXISTS ( SELECT 1
