--
-- Name: guild_members guild_members_delete_own; Type: POLICY; Schema: social_features; Owner: gamilit_user
--

CREATE POLICY guild_members_delete_own ON social_features.guild_members FOR DELETE USING (((user_id = gamilit.get_current_user_id()) AND (NOT (((role)::text = 'leader'::text) AND (NOT (EXISTS ( SELECT 1
   FROM social_features.guild_members gm2
  WHERE ((gm2.guild_id = guild_members.guild_id) AND ((gm2.role)::text = 'leader'::text) AND (gm2.user_id <> guild_members.user_id)))))))));


--
-- Name: POLICY guild_members_delete_own ON guild_members; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY guild_members_delete_own ON social_features.guild_members IS 'Users can leave guilds (leaders must transfer leadership first)';


--
-- Name: guild_members guild_members_insert_own; Type: POLICY; Schema: social_features; Owner: gamilit_user
--

CREATE POLICY guild_members_insert_own ON social_features.guild_members FOR INSERT WITH CHECK (((user_id = gamilit.get_current_user_id()) AND (EXISTS ( SELECT 1
   FROM social_features.guilds g
  WHERE ((g.id = guild_members.guild_id) AND (g.is_public = true) AND (g.is_active = true) AND (g.member_count < 20))))));


--
-- Name: POLICY guild_members_insert_own ON guild_members; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY guild_members_insert_own ON social_features.guild_members IS 'Users can join recruiting guilds with available capacity';


--
-- Name: guild_members guild_members_leader_manage; Type: POLICY; Schema: social_features; Owner: gamilit_user
--

CREATE POLICY guild_members_leader_manage ON social_features.guild_members USING ((EXISTS ( SELECT 1
   FROM social_features.guild_members gm
  WHERE ((gm.guild_id = guild_members.guild_id) AND (gm.user_id = gamilit.get_current_user_id()) AND ((gm.role)::text = ANY ((ARRAY['leader'::character varying, 'officer'::character varying])::text[])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM social_features.guild_members gm
  WHERE ((gm.guild_id = guild_members.guild_id) AND (gm.user_id = gamilit.get_current_user_id()) AND (((gm.role)::text = 'leader'::text) OR (((gm.role)::text = 'officer'::text) AND ((guild_members.role)::text = 'member'::text)))))));


--
-- Name: POLICY guild_members_leader_manage ON guild_members; Type: COMMENT; Schema: social_features; Owner: gamilit_user
--

COMMENT ON POLICY guild_members_leader_manage ON social_features.guild_members IS 'Guild leaders can manage all members, officers can manage regular members';


